/* =============================================================================
   Atlas de Arquitecturas — js/content/yolo-world.js
   Página de modelo: YOLO-World (Cheng et al., CVPR 2024, arXiv:2401.17270; repo oficial
   AILab-CVC/YOLO-World, sobre mmyolo). Ancla de comparación: YOLOv8-L (Ultralytics), config
   'yolov8l-640' (solo calculador, sin página).
   Plantilla fija de 11 secciones (SPEC §5.3).
   Regla: ningún número de la arquitectura se escribe a mano. Formas, parámetros y
   MACs salen del calculador (bloques op/trace/params/flops/scaling/compare y
   cantidades {{config.ruta}}, SPEC §6.6). Los números de entrenamiento y los
   resultados citan sección o tabla del paper (arXiv v3) o el archivo del repo oficial. Sin DOM al cargar.
   ========================================================================== */
(function (root) {
  'use strict';
  const ATLAS = (root.ATLAS = root.ATLAS || {});

  // LaTeX dentro de HTML: String.raw para no duplicar barras invertidas.
  const R = String.raw;
  // Estimación (SPEC §5.4): subrayado punteado + "est."
  const est = (s) => '<span class="est">' + s + '</span>';
  // Cantidades del calculador (SPEC §6.6). C = configuración canónica.
  const C = 'yolo-world-l-640';
  const Y8 = 'yolov8l-640';
  const GD = 'grounding-dino-t';
  const GD672 = 'grounding-dino-t-672';   // el mismo Grounding DINO-T a 672×672 (escala parecida a 640)
  const DT = 'detr-r50-640';
  const qn = (path, cfg) => '{{' + (cfg || C) + '.' + path + '}}';
  const sh = (id, cfg) => qn('tensor.' + id + '.shape', cfg);   // 6400×80
  const sy = (id, cfg) => qn('tensor.' + id + '.sym', cfg);     // HW×V
  const np = (id, cfg) => qn('node.' + id + '.params', cfg);    // parámetros del nodo (× repeat ya aplicado)
  const nm = (id, cfg) => qn('node.' + id + '.macsG', cfg);     // GMACs del nodo
  const npc = (id, cfg) => qn('node.' + id + '.macsPct', cfg);  // % de los MACs del nodo
  // Claves de la config (nombres del calculador, js/arch/yolo-world.js).
  const cV = (cfg) => qn('cfg.V', cfg);       // vocabulario (clases de texto)
  const cE = (cfg) => qn('cfg.E', cfg);       // ancho del embedding de texto (CLIP ViT-B/32: 512)
  const cR = (cfg) => qn('cfg.regMax', cfg);  // bins de la DFL por lado
  const tP = qn('quantities.textEncoderParams');   // parámetros del text encoder de CLIP (offline, fuera de los totales)
  const tM = qn('quantities.promptTextMacs');      // MACs del text encoder por prompt (77 tokens)

  const PAPER = 'Cheng et al., <i>YOLO-World: Real-Time Open-Vocabulary Object Detection</i>, CVPR 2024, arXiv:2401.17270';
  const REPO = '<a href="https://github.com/AILab-CVC/YOLO-World" target="_blank" rel="noopener">AILab-CVC/YOLO-World</a>';
  const GDINO = 'Liu et al., <i>Grounding DINO</i>, ECCV 2024, arXiv:2303.05499';

  ATLAS.register({
    id: 'yolo-world',
    kind: 'model',
    sections: [
      // ======================================================== 1
      {
        id: 'para-que',
        titleEn: 'What it is for',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`<b>En una frase:</b> YOLO-World recibe una imagen (${sh('x-img')}) y una <b>lista de palabras</b> que tú eliges ("person", "forklift", "safety helmet"), y devuelve cajas con la palabra que las nombra. Por dentro es un YOLOv8: mismo backbone, mismo neck PAN (con dos agregados), misma cabeza de cajas con DFL, misma asignación TAL y el mismo NMS al final. Lo único que cambia de fondo es la <b>cabeza de clase</b>: en vez de una conv que da K logits fijos, da un <b>embedding</b> por posición que se compara con los embeddings de texto de esas palabras (calculados con el text encoder de CLIP).` },
          { t: 'p', html: R`El truco que lo hace práctico se llama <b>prompt-then-detect</b> (${PAPER}): las palabras se codifican <b>una vez</b>, offline, y sus embeddings se guardan como pesos de convoluciones 1×1. En deploy no corre ningún text encoder: queda un YOLO con ${cV()} clases cuyos pesos los escribió CLIP. Si mañana necesitas otra clase, vuelves a codificar la lista y re-exportas; no reentrenas.` },
          { t: 'table', caption: 'Cuándo sí y cuándo no', head: ['Situación', '¿YOLO-World?', 'Por qué'], rows: [
            ['Detectar clases que cambian con frecuencia o que no tienen datos etiquetados (un robot de almacén que hoy busca "pallet" y mañana "carrito")', 'Sí', 'Cambiar el vocabulario es volver a codificar texto; la red no se toca.'],
            ['Tiempo real en GPU o edge, con un vocabulario conocido al inicio de la sesión', 'Sí', 'Con el vocabulario re-parametrizado, el costo es el de un YOLOv8-L más un poco de neck: 52.0 FPS en V100 sin TensorRT para la versión L, frente a 1.5 de Grounding DINO-T (Tabla 2 del paper).'],
            ['Pre-etiquetar un dataset nuevo (proponer cajas que un humano corrige)', 'Sí', 'Rápido y barato. Para etiquetado offline, compara en tu dominio antes de elegir: en LVIS minival zero-shot YOLO-World-L supera a Grounding DINO-T y -L (35.4 vs 27.4 y 33.9 Fixed AP), mientras que Grounding DINO gana en COCO y con frases con atributos, y OWLv2 en clases raras.'],
            ['Frases referenciales largas ("la taza roja a la izquierda del teclado")', 'Con cuidado', 'El texto se reduce a un vector por frase y la fusión con la imagen es liviana; los modelos de grounding con fusión profunda (Grounding DINO) entienden mejor relaciones y atributos.'],
            ['Un vocabulario fijo de pocas clases con muchos datos etiquetados (tu línea de producción con 5 tipos de pieza)', 'Úsalo como punto de partida', 'Un YOLOv8 entrenado en tus datos suele igualarlo; el valor de YOLO-World es el preentrenamiento (fine-tuning con menos datos y épocas) y poder sumar clases después.'],
            ['Clases muy finas o jerga de tu dominio ("defecto tipo B", códigos de pieza)', 'No tal cual', 'CLIP no conoce esas palabras con ese significado: el zero-shot falla. Haz fine-tuning o usa prompts visuales (YOLOE, YOLO-World-Image).'],
          ] },
          { t: 'callout', kind: 'interview', html: R`<p>"YOLO-World is a YOLOv8 whose classification head outputs an object embedding per anchor point instead of fixed class logits; class scores are scaled cosine similarities with CLIP text embeddings of whatever vocabulary you give it. A vision-language PAN injects the text into the multi-scale features. Because the vocabulary is encoded offline and folded into 1×1 conv weights, inference costs about the same as a YOLO, which is the whole point versus Grounding DINO."</p>` },
        ],
      },

      // ======================================================== 2
      {
        id: 'puente',
        titleEn: 'Bridge from what you know',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`<b>Como YOLOv8-L, pero la última conv 1×1 de la rama de clase ya no termina en K canales: termina en ${cE()} canales que se comparan con texto.</b> Empieza por lo que conoces. En YOLOv8 a 640×640, la cabeza desacoplada predice en tres niveles (strides 8, 16, 32): ${qn('quantities.p3Side', Y8)}² + ${qn('quantities.p4Side', Y8)}² + ${qn('quantities.p5Side', Y8)}² = ${qn('quantities.anchors', Y8)} puntos de anclaje (anchor-free: un punto por celda, sin anchors de forma). En cada punto, la rama de caja da 4 distribuciones de ${cR(Y8)} bins (DFL) y la rama de clase da K logits con sigmoide (BCE, sin objectness). TAL asigna a cada GT los top-10 puntos según una métrica que mezcla puntuación de clase e IoU; en inferencia, umbral + NMS.` },
          { t: 'p', html: R`YOLO-World conserva <b>todo eso</b> y cambia el final de la rama de clase. La conv 1×1 que daba K canales ahora da un vector de ${cE()} por punto (un "object embedding"); el logit de la clase j es el coseno entre ese vector y el embedding de texto de la palabra j, escalado y desplazado: \(s_{k,j} = \alpha\,\hat e_k\cdot\hat w_j + \beta\). Es la misma idea que el <a href="#clip">clasificador zero-shot de CLIP</a>, pero aplicada en cada uno de los ${qn('quantities.anchors')} puntos en vez de una vez por imagen. Las otras dos piezas nuevas están en el neck (RepVL-PAN): una que inyecta el texto en las features de imagen y otra (que la v2 quitó) que actualiza el texto con la imagen.` },
          { t: 'table', caption: 'YOLOv8 ↔ YOLO-World: qué se queda, qué cambia', head: ['Pieza', 'YOLOv8-L', 'YOLO-World-L', '¿Cambia?'], rows: [
            ['Backbone', 'CSPDarknet con C2f + SPPF; salidas C3, C4, C5 (strides 8, 16, 32)', 'La misma arquitectura, preentrenada sobre O365 + GoldG (+ CC3M). La config de preentrenamiento del repo no define <code>load_from</code> ni pesos iniciales para el backbone: no parte de YOLOv8-COCO (revisa <code>load_from</code> en la config que uses para fine-tuning)', 'Igual'],
            ['Neck', 'PAN: top-down + bottom-up con bloques C2f', R`<b>RepVL-PAN</b>: el mismo PAN, pero cada C2f es un <b>T-CSPLayer</b> (C2f + max-sigmoid attention con el texto) y, en la v1, una <b>image-pooling attention</b> que actualiza los embeddings de texto con la imagen`, '<b>Nuevo</b>'],
            ['Rama de caja', R`conv 3×3 → conv 3×3 → conv 1×1 a 4·R (R = ${cR(Y8)} bins); DFL + CIoU`, 'Idéntica', 'Igual'],
            ['Rama de clase', 'conv 3×3 → conv 3×3 → conv 1×1 a K logits', R`conv 3×3 → conv 3×3 → conv 1×1 a ${cE()} (object embedding) → <b>cabeza contrastiva región-texto</b>: coseno con el texto, × α + β`, '<b>Cambia</b>'],
            ['Número de clases', 'K fijo al entrenar (80 en COCO); cambiarlo = reentrenar la última conv', R`V = tamaño del vocabulario que tú pasas (${cV()} en la config canónica); cambiarlo = recodificar texto`, '<b>Cambia</b>'],
            ['De dónde salen los pesos de clase', 'Aprendidos por gradiente, uno por clase', 'Embeddings del text encoder de CLIP (congelado en el preentrenamiento), uno por palabra o frase', '<b>Nuevo</b>'],
            ['Pérdida de clase', 'BCE con objetivos suaves de TAL', R`"Región-texto contrastiva" en el paper; en el código, la misma BCE con sigmoide sobre los V logits región-texto (ver <a href="#yolo-world.entrenamiento">entrenamiento</a>)`, 'Equivale'],
            ['Asignación', 'TAL (Task-Aligned, de TOOD), uno a muchos', 'TAL igual; la "clase" de cada positivo es el índice de su texto en el vocabulario del mosaico', 'Igual'],
            ['Post-proceso', 'Umbral + NMS (IoU 0.7 por defecto)', 'Umbral + NMS igual (IoU 0.7 en la config de mmyolo); la salida sigue siendo densa y uno a muchos', 'Igual'],
            ['Datos', 'COCO (80 clases), desde cero', 'Objects365 (365 clases) + GoldG (frases de grounding) + CC3M con pseudo-etiquetas: 100 épocas de preentrenamiento (§4.2)', '<b>Cambia</b>'],
          ] },
          { t: 'compare', models: [Y8, C], rows: ['params', 'macs'], caption: 'YOLOv8-L vs YOLO-World-L a 640×640 (detector, sin el text encoder): cuánto agregan RepVL-PAN y la cabeza contrastiva' },
          { t: 'p', html: R`Lectura: el detector de YOLO-World-L tiene ${qn('params.total')} parámetros frente a ${qn('params.total', Y8)} de YOLOv8-L, y ${qn('macs.totalG')} MACs frente a ${qn('macs.totalG', Y8)}. Son ${qn('metrics.deltaParamsVsYolov8')} parámetros más y ${qn('metrics.macsVsYolov8')} veces los MACs. Casi todo está en el neck: ${np('neck')} parámetros frente a ${np('neck', Y8)} (la max-sigmoid de los cuatro T-CSPLayers, ${qn('quantities.maxSigmoidParams')}, una rama más que concatenar en cada uno y la image-pooling attention, ${qn('quantities.ipaParams')}). La rama de clase cambia poco: ${np('head-text')} frente a ${np('head-cls', Y8)}; lo único nuevo es que su última conv 1×1 da ${cE()} canales en vez de K. El text encoder de CLIP (${tP} parámetros) no está en esa cuenta: corre una vez por vocabulario, no por imagen.` },
          { t: 'callout', kind: 'trap', title: '"YOLO-World es un detector tipo DETR con texto"', html: R`<p>No. Es un detector <b>denso</b>: una predicción por punto de anclaje, asignación uno a muchos (TAL) y <b>NMS</b> en inferencia, igual que YOLOv8. No tiene queries, ni matching húngaro, ni decoder. El que sí es "DETR con texto" es <a href="#grounding-dino">Grounding DINO</a>. Si te preguntan "¿YOLO-World necesita NMS?", la respuesta es sí, por la misma razón que YOLOv8: varios puntos de anclaje son positivos para el mismo objeto.</p>` },
          { t: 'callout', kind: 'connect', html: R`<p>La cabeza de clase es el <a href="#clip">clasificador zero-shot de CLIP</a> por posición: CLIP compara <b>un</b> embedding de imagen con los textos de las clases; YOLO-World compara los ${qn('quantities.anchors')} embeddings de región con esos mismos textos. La escala α y el desplazamiento β son el <code>logit_scale</code> de CLIP más un sesgo, que hace falta porque aquí la pérdida es una sigmoide por clase y casi todos los puntos son fondo.</p>` },
        ],
      },

      // ======================================================== 3
      {
        id: 'diagrama',
        titleEn: 'Block diagram',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`Dos carriles. <b>Offline</b> (arriba, marco ámbar punteado): el vocabulario pasa por el text encoder de CLIP una vez y queda una matriz ${sy('vocab')} = ${sh('vocab')}. <b>Online</b> (por cada imagen): la imagen pasa por el backbone (C3, C4, C5), el RepVL-PAN mezcla esas features con el vocabulario y da P3, P4, P5, y en cada nivel la cabeza produce cajas (rama DFL) y logits región-texto (rama de clase contra el vocabulario). Al final, umbral + NMS como en cualquier YOLO. Abre el neck para ver los T-CSPLayers; "Recorrido" sigue la imagen con números.` },
          { t: 'archdiagram', diagram: 'yolo-world-overview', walk: 'forward', wide: true, caption: R`YOLO-World-L @ 640: ${sh('x-img')} → C3/C4/C5 → RepVL-PAN (con el vocabulario ${sh('vocab')}) → P3/P4/P5 → por nivel, cajas y logits ${sy('logits-p3')}. El text encoder corre offline. Formas del calculador.` },
          { t: 'p', html: R`La figura que resume el argumento de costo del paper: dónde corre el text encoder. En Grounding DINO, cada imagen paga BERT y la fusión profunda imagen-texto; en YOLO-World, el texto se codifica una vez y la imagen solo paga el detector:` },
          { t: 'viz', kind: 'prompt-then-detect', params: { yw: C, gd: GD, V: 80, n: 1000, mode: 'reparam' }, caption: R`MACs del calculador para YOLO-World-L y Grounding DINO-T con el vocabulario elegido. "Online" es lo que se paga por imagen; MACs no es latencia (NMS, kernels de atención y memoria no aparecen).` },
          { t: 'p', html: R`Y la cabeza de clase en sí: a la izquierda, una conv 1×1 con K filas aprendidas; a la derecha, las mismas filas escritas por el text encoder. Escribe una palabra nueva y mira cómo aparece una fila nueva (y un canal de salida nuevo) sin tocar el resto:` },
          { t: 'viz', kind: 'open-vocab-head', params: { config: C, anchor: Y8 }, caption: 'Embeddings y similitudes ilustrativos (vectores sintéticos de pocas dimensiones): muestran el mecanismo, no valores reales de CLIP.' },
          { t: 'callout', kind: 'note', html: R`<p>Tres detalles del diagrama: (1) el vocabulario entra al neck (T-CSPLayers) <b>y</b> a la cabeza: no es solo un clasificador al final; (2) la image-pooling attention (el camino imagen → texto) solo existe en la v1 del paper: la v2 del repo la quitó porque complicaba el export (<a href="#yolo-world.variantes">variantes</a>); (3) NMS sigue al final, fuera de la red.</p>` },
        ],
      },

      // ======================================================== 4
      {
        id: 'operaciones',
        titleEn: 'Operations per block',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`Primero la cabeza de clase con un ejemplo chico, sin notación (números ilustrativos, calculados a mano). Tres palabras en el vocabulario: "person", "forklift", "pallet". Un punto de anclaje de P4 que cae sobre un montacargas produce un object embedding; lo normalizas, normalizas los tres embeddings de texto y haces tres productos punto: cosenos 0.21, <b>0.34</b> y 0.18. Con la escala α ≈ 14.3 (la inicialización de CLIP, 1/0.07) y un sesgo β = −5: logits −2.0, −0.14 y −2.4; con sigmoide, 0.12, <b>0.46</b> y 0.08. Gana "forklift". Si agregas "truck" al vocabulario, aparece un cuarto coseno; los tres primeros logits no cambian (cada clase es una fila independiente).` },
          { t: 'callout', kind: 'why', title: 'Por qué los cosenos son tan chicos y aun así funciona', html: R`<p>En CLIP, los cosenos imagen-texto de pares correctos suelen ser del orden de 0.2–0.35 ${est('(orden de magnitud típico de CLIP ViT-B/32; míralo con tus propios embeddings)')}; es el <i>modality gap</i> de <a href="#clip">CLIP</a>: imagen y texto viven en zonas distintas de la esfera. Lo que importa es la diferencia entre clases, y α la amplifica. Por eso α existe y se aprende. Sin α, todos los logits quedarían en [−1, 1] y la sigmoide no podría separar 0.46 de 0.12. Y β existe porque con sigmoide por clase y miles de puntos de fondo, el logit por defecto tiene que ser muy negativo. El código oficial lo inicializa con el prior de clase de YOLOv8, \(\log\big(5/V/(640/\text{stride})^2\big)\) ("unos 5 objetos por imagen de 640"), que con V = 80 da ≈ −11.5, −10.1 y −8.8 en strides 8, 16 y 32 (<code>yolo_world_head.py</code>); Ultralytics arranca β en −10.</p>` },
          { t: 'table', caption: 'Símbolos de esta página', head: ['Símbolo', 'Qué es', 'YOLO-World-L @ 640'], rows: [
            ['H × W', 'imagen de entrada', R`${qn('cfg.H')} × ${qn('cfg.W')}`],
            ['C3, C4, C5', 'salidas del backbone en strides 8, 16, 32', R`${sh('c3')}, ${sh('c4')}, ${sh('c5')}`],
            ['P3, P4, P5', 'salidas del neck (RepVL-PAN), entrada de la cabeza', R`${sh('p3')}, ${sh('p4')}, ${sh('p5')}`],
            ['V', 'tamaño del vocabulario (palabras o frases); el paper lo llama C', cV()],
            ['E', 'ancho del embedding de texto y del object embedding (CLIP ViT-B/32); el paper lo llama D', cE()],
            ['HW', 'puntos de anclaje de un nivel (una predicción por celda)', R`${qn('quantities.anchors')} en total en los 3 niveles`],
            ['α, β', 'escala y desplazamiento aprendidos de la cabeza contrastiva', 'escalares'],
          ], note: 'El paper usa C para el número de palabras y D para el ancho del embedding; en el Atlas, V es el vocabulario y D/E anchos (SPEC §6.2). K en el paper es el número de predicciones, no de clases.' },
          { t: 'callout', kind: 'trap', title: 'C, D y K del paper ≠ los del Atlas', html: R`<p>En el paper, \(W\in\mathbb{R}^{C\times D}\) son los embeddings de texto (C palabras de D dimensiones) y \(K\) el número de predicciones. En el Atlas eso es \(V\times E\) y "puntos de anclaje"; C es canales y K, clases. Si lees el paper con la página al lado, traduce.</p>` },

          { t: 'h3', text: 'Backbone: el de YOLOv8-L' },
          { t: 'op', block: 'backbone', model: 'yolo-world', title: 'CSPDarknet con C2f y SPPF (YOLOv8-L)',
            tex: R`\{\mathbf{C}_3,\mathbf{C}_4,\mathbf{C}_5\} = \mathrm{Backbone}(\mathbf{x}),\qquad \mathbf{C}_l\in\mathbb{R}^{\frac{H}{2^l}\times\frac{W}{2^l}\times c_l}`,
            in: ['x-img'], out: ['c3', 'c4', 'c5'], params: true, flops: true,
            what: R`El mismo backbone que YOLOv8-L: convs 3×3 con stride 2 y bloques C2f (CSP con dos convs y bottlenecks), con SPPF al final. Salen tres mapas: ${sh('c3')}, ${sh('c4')} y ${sh('c5')}.`,
            why: R`El paper no toca el backbone a propósito: el argumento es que un detector chico y rápido, con el preentrenamiento correcto, alcanza vocabulario abierto. Todo lo multimodal vive en el neck y la cabeza. Es también lo que permite reusar todo el tooling de YOLO (export, cuantización, fusión de BN).` },

          { t: 'h3', text: 'Neck: RepVL-PAN' },
          { t: 'p', html: R`El PAN de YOLOv8 (top-down: P5 → P4 → P3 con upsampling y concatenación; bottom-up: P3 → P4 → P5 con convs de stride 2), con dos agregados. El <b>T-CSPLayer</b> reemplaza a cada C2f del neck: es un C2f con un bloque más al final, la <b>max-sigmoid attention</b>, que re-pondera los canales de cada posición según cuánto se parece esa posición a la palabra del vocabulario que mejor le responde. La <b>image-pooling attention</b> va en sentido contrario: resume la imagen en pocos tokens y actualiza los embeddings de texto con ellos.` },
          { t: 'archdiagram', diagram: 'yw-repvl-pan', wide: true, caption: R`RepVL-PAN de YOLO-World-L: caminos top-down y bottom-up en strides 8, 16 y 32, con un T-CSPLayer en cada fusión y la image-pooling attention (v1) entre ambos. Formas del calculador.` },
          { t: 'op', block: 't-csp', model: 'yolo-world', diagram: 'yw-repvl-pan', title: 'T-CSPLayer: C2f + max-sigmoid attention (texto → imagen)',
            tex: R`\mathbf{X}_l' = \mathbf{X}_l\cdot\delta\Big(\max_{j\in\{1..V\}}\big(\mathbf{X}_l\,\mathbf{W}_j^{\top}\big)\Big)^{\!\top}`,
            in: ['td4-cat'], out: ['p4-td'], params: true, flops: true,
            what: R`La ecuación 2 del paper: para cada posición de un mapa \(\mathbf{X}_l\), se calcula la similitud con cada una de las V palabras, se toma el <b>máximo</b> sobre las palabras y se pasa por una sigmoide δ. Ese número en (0, 1) multiplica los canales de la posición. La salida se concatena con las demás ramas del C2f ("cross-stage") antes de su conv final. Las similitudes de un T-CSPLayer de P3 forman un tensor ${sh('td3-tg-scores')} (${sy('td3-tg-scores')}): cabezas × posiciones × palabras. En el código oficial hay más detalle que la ecuación no muestra: el texto pasa por una lineal (512 → canales de embedding), la similitud se hace <b>por cabezas</b> (cada cabeza re-pondera su grupo de canales), se divide por \(\sqrt{d}\), se suma un sesgo aprendido por cabeza, y lo que se multiplica no es \(\mathbf{X}_l\) sino una conv 3×3 + BN de \(\mathbf{X}_l\) (<code>MaxSigmoidAttnBlock</code>). Esa conv 3×3 es casi todo el costo en parámetros de la max-sigmoid (${qn('quantities.maxSigmoidParams')} en los cuatro T-CSPLayers); la lineal del texto y los sesgos son poco.`,
            why: R`Es una atención <b>sin softmax ni suma ponderada</b>: no trae información del texto a la imagen, solo decide cuánto "encender" cada posición según si se parece a algo del vocabulario. El máximo hace que la operación no dependa de cuántas palabras hay ni de su orden, y que una posición se encienda si se parece a <i>cualquier</i> clase pedida. Por eso es barata (un producto por posición y palabra, sin N²) y re-parametrizable: con el vocabulario fijo, el producto con las V palabras es una conv 1×1 de V filas (Apéndice A.1). Tabla 4: agregar los T-CSPLayers (T→I) sube de 22.4 a 23.2 AP zero-shot en LVIS preentrenando solo en O365.` },
          { t: 'op', block: 'img-pool-attn', model: 'yolo-world', diagram: 'yw-repvl-pan', title: 'Image-pooling attention (imagen → texto, solo v1)',
            tex: R`\tilde{\mathbf X} = \mathrm{concat}\big(\mathrm{MP}_{3\times3}(\mathbf X_3),\,\mathrm{MP}_{3\times3}(\mathbf X_4),\,\mathrm{MP}_{3\times3}(\mathbf X_5)\big)\in\mathbb R^{27\times d},\qquad \mathbf W' = \mathbf W + \mathrm{MHA}(\mathbf W,\tilde{\mathbf X},\tilde{\mathbf X})`,
            in: ['p3', 'p4-td', 'c5'], out: ['vocab-upd'], params: true, flops: true,
            what: R`Cada uno de los tres mapas se proyecta con una conv 1×1 y se reduce con <b>max pooling adaptativo a 3×3</b>: 9 tokens por nivel, 27 en total (§3.3, ec. 3): ${sh('ipa-tokens')}, con d el ancho de esta atención. Los mapas son P3 y P4 del camino top-down y C5. Las V palabras son las queries; los 27 tokens, claves y valores. La salida se suma al vocabulario (residual): ${sh('vocab')} → ${sh('vocab-upd')}. Ese vocabulario actualizado guía solo a los T-CSPLayers del camino bottom-up: la cabeza sigue usando el original (así es en el código oficial, <code>YOLOWorldDualPAFPN</code>, y en Ultralytics: el neck no devuelve el texto).`,
            why: R`Hace que el embedding de "apple" se acerque a la fruta o a la marca según lo que hay en <i>esta</i> imagen: texto consciente de la imagen. Pooling a 3×3 en vez de cross-attention sobre todas las posiciones mantiene el costo mínimo (27 claves, sin importar la resolución): ${qn('quantities.ipaParams')} parámetros. Tabla 4: suma 0.3 AP (23.2 → 23.5) sobre los T-CSPLayers. El precio práctico: el vocabulario ya no es constante por imagen, así que ya no se puede plegar del todo en pesos. La v2 del repo la quitó por eso (empeoraba la velocidad tras exportar a ONNX/TensorRT).` },

          { t: 'h3', text: 'Cabeza: cajas con DFL y clases contra el texto' },
          { t: 'op', block: 'head-text', model: 'yolo-world', title: 'Cabeza contrastiva región-texto (rama de clase)',
            tex: R`s_{k,j} = \alpha\cdot\frac{\mathbf e_k}{\lVert\mathbf e_k\rVert_2}\cdot\Big(\frac{\mathbf w_j}{\lVert\mathbf w_j\rVert_2}\Big)^{\!\top} + \beta,\qquad \mathbf e_k\in\mathbb R^{E},\ \ \mathbf w_j\in\mathbb R^{E}`,
            in: ['p3'], out: ['obj-emb-p3', 'logits-p3'], params: true, flops: true,
            what: R`Ecuación 1 del paper. En cada nivel, dos convs 3×3 y una conv 1×1 dan un object embedding de ${cE()} por punto: en P3, ${sh('obj-emb-p3')}. Se normaliza cada embedding (L2 sobre los canales) y cada fila del vocabulario, se hace el producto punto y se aplica la afinidad aprendida: logits ${sh('logits-p3')} (${sy('logits-p3')}). Igual en P4 (${sh('logits-p4')}) y P5 (${sh('logits-p5')}). En el código, α = exp(logit_scale), inicializado en 1/0.07 como en CLIP (la cabeza BN de la v2 arranca en e⁻¹).`,
            why: R`La normalización L2 convierte el producto punto en un coseno: la magnitud del embedding no puede "ganar" una clase por sí sola, y el texto de CLIP, que vive en una esfera, se compara en su propia escala. El paper dice que las normas L2 y la afinidad (α, β) son importantes para estabilizar el entrenamiento región-texto (§3.2). Con el vocabulario fijo, todo esto es una conv 1×1 con pesos \(\alpha\,\hat{\mathbf w}_j\) y sesgo β aplicada al embedding normalizado (ver el ejercicio de <a href="#yolo-world.practica">práctica</a>). La v2 cambia la L2 de la imagen por una <b>BatchNorm</b>: en inferencia BN es afín por canal y se pliega en esa conv, así que la cabeza entera queda en una sola conv 1×1.` },
          { t: 'op', block: 'head-box', model: 'yolo-world', title: 'Rama de caja: DFL (igual que YOLOv8)',
            tex: R`\hat d_s = \sum_{i=0}^{R-1} i\cdot\mathrm{softmax}(\mathbf z_s)_i,\quad s\in\{l,t,r,b\},\qquad \hat{\mathbf b} = (x - \hat d_l,\ y - \hat d_t,\ x + \hat d_r,\ y + \hat d_b)\cdot\text{stride}`,
            in: ['p3'], out: ['boxes-p3'], params: true, flops: true,
            what: R`Dos convs 3×3 y una conv 1×1 a 4·R canales: para cada lado de la caja, una distribución de R = ${cR()} bins sobre la distancia (en unidades de stride) desde el punto de anclaje. La distancia es la esperanza de esa distribución. Salida de P3: ${sh('boxes-p3')}.`,
            why: R`Sin cambios respecto de YOLOv8, y es una de las razones por las que YOLO-World conserva la precisión de localización de un YOLO: la parte "dónde" del detector no depende del texto. Solo la parte "qué" pasa por el vocabulario. Por eso, en la Tabla 6, fine-tuneado en COCO sin RepVL-PAN, queda a la par de YOLOv8-L (53.3 vs 52.9 AP).` },

          { t: 'h3', text: 'Text encoder: CLIP, offline' },
          { t: 'op', block: 'txt-encoder', model: 'yolo-world', title: 'Text encoder de CLIP ViT-B/32 (congelado, una vez por vocabulario)',
            tex: R`\mathbf W = \mathrm{TextEncoder}(\{t_1,\ldots,t_V\})\in\mathbb R^{V\times E},\qquad \mathbf w_j = \mathrm{proj}\big(\mathrm{Transformer}(\mathrm{tokens}(t_j))_{\text{EOT}}\big)`,
            in: ['prompts'], out: ['vocab'],
            what: R`El text encoder de la <a href="#clip">página de CLIP</a>: transformer causal de {{clip-vit-b32.cfg.Lt}} capas sobre hasta {{clip-vit-b32.cfg.T}} tokens BPE; el estado del token EOT pasa por una proyección lineal a ${cE()}. Cada palabra o frase del vocabulario da una fila. En el código oficial es <code>openai/clip-vit-base-patch32</code> de HuggingFace, congelado durante el preentrenamiento (§4.2). Si el texto es una frase larga (caption o expresión referencial), el paper extrae frases nominales con n-gramas antes de codificarlas.`,
            why: R`Tabla 5: con el text encoder congelado, CLIP da 22.4 AP zero-shot en LVIS frente a 14.6 de BERT-base (APr 14.5 vs 3.4). CLIP aprendió texto alineado con imágenes; BERT, texto alineado con texto. Y descongelarlo empeora: fine-tunear CLIP sobre O365 baja a 19.3 AP (los autores lo atribuyen a que 365 categorías degradan la generalidad del encoder). Cuesta ${tP} parámetros y ${tM} MACs <b>por palabra</b> con el contexto completo de 77 tokens (${sh('prompts')} ids para el vocabulario canónico): así, codificar las ${cV()} palabras cuesta ${qn('metrics.vocabTextToOnline')} veces el forward de una imagen. Ese es el <b>peor caso</b>: es la convención del calculador y de Ultralytics (<code>clip.tokenize</code> siempre rellena a 77). El repo oficial tokeniza con el tokenizer de HuggingFace y <code>padding=True</code> (<code>HuggingCLIPLanguageBackbone</code>), es decir, rellena hasta el prompt más largo de la lista; con nombres de clase de una a tres palabras eso es del orden de 5 tokens, y el costo baja ${est('unas 15 veces (≈ 77/5; depende del nombre más largo del vocabulario), a una fracción del forward de una imagen')}. En los dos casos se paga una vez por vocabulario, no por imagen; por eso el calculador lo deja fuera de los totales del detector.` },
          { t: 'callout', kind: 'skip', html: R`<p><b>Sáltate esto</b> si vas corto: los detalles de implementación del T-CSPLayer (canales de embedding y número de cabezas por nivel, la conv 3×3 del <code>project_conv</code>) y la versión re-parametrizada de la image-pooling attention (ec. 5–6 del apéndice). En entrevista basta con: "max-sigmoid attention re-pondera las features por la similitud máxima con el vocabulario; image-pooling attention actualiza el texto con 27 tokens de imagen".</p>` },

          { t: 'h3', text: 'El recorrido completo con números' },
          { t: 'p', html: R`Cada fila es un tensor en orden forward, de la imagen a los logits y las cajas de los tres niveles, más el vocabulario. Toca una fila para resaltar el tensor en el diagrama.` },
          { t: 'trace', model: 'yolo-world' },
        ],
      },

      // ======================================================== 5
      {
        id: 'costo',
        titleEn: 'Parameters and cost',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`El detector de YOLO-World-L (sin el text encoder) tiene ${qn('params.total')} parámetros (${qn('params.totalM')}): backbone ${np('backbone')}, neck ${np('neck')}, rama de caja ${np('head-box')} y rama de clase ${np('head-text')}. A 640×640 cuesta ${qn('macs.totalG')} MACs con V = ${cV()}: backbone ${nm('backbone')}, neck ${nm('neck')}, cabezas ${nm('head-box')} + ${nm('head-text')}. El paper reporta 48M parámetros re-parametrizados y 110M con el text encoder incluido (Tabla 2); la diferencia es justo el text encoder de CLIP (${tP} en el calculador).` },
          { t: 'params', model: 'yolo-world', group: 'block' },
          { t: 'flops', model: 'yolo-world' },
          { t: 'callout', kind: 'trap', title: '"GFLOPs" de Ultralytics y del paper', html: R`<p>Los MACs del calculador cuentan multiplicación + suma como uno; FLOPs = 2 × MACs (${qn('flops.totalG')}FLOPs). Ultralytics imprime "GFLOPs" calculados con thop como 2 × MACs, así que sus números sí son FLOPs; muchos papers de detección (y fvcore) escriben "FLOPs" para MACs. Antes de comparar, pregunta qué cuenta cada uno, a qué resolución y si incluye el text encoder.</p>` },
          { t: 'h3', text: 'Vocabulario: lo que crece con V' },
          { t: 'p', html: R`El costo que depende de V es pequeño: en cada T-CSPLayer, un producto de cada posición contra V palabras; en la cabeza, una conv 1×1 de ${cE()} → V canales por nivel. Ambos son lineales en V y en el número de posiciones. El explorador parte de la config canónica (V = ${cV()}); súbelo a 1203 (las clases de LVIS) y mira qué pasa:` },
          { t: 'scaling', model: 'yolo-world', knobs: [{ key: 'V', values: [1, 20, 80, 365, 1203] }], show: ['params', 'macs'] },
          { t: 'p', html: R`<b>La ley en palabras:</b> ×V en el vocabulario → lineal en la parte texto-dependiente de la cabeza y del neck; el resto (backbone, convs del PAN, rama de caja) no cambia. Pasar de 80 a 1203 clases encarece una parte chica del total; lo que más pesa con vocabularios grandes en la práctica es el post-proceso (más pares caja-clase sobre el umbral entran a NMS) ${est('(mídelo con tu vocabulario: el número de candidatas depende del umbral y de la escena)')}.` },
          { t: 'h3', text: 'Resolución: ×2 de lado → ×4 en todo' },
          { t: 'scaling', model: 'yolo-world', knobs: [{ key: 'res', values: [320, 640, 960, 1280] }], show: ['tokens', 'macs'] },
          { t: 'p', html: R`Es una red convolucional sin atención global: los MACs crecen con el área (×4 por cada ×2 de lado), igual que YOLOv8. No hay término N² que explote: la max-sigmoid es lineal en posiciones y la image-pooling attention siempre ve 27 tokens. Por eso el repo ofrece versiones a 1280 para objetos chicos (preentrenamiento continuado a esa resolución).` },
          { t: 'h3', text: 'YOLOv8-L, YOLO-World-L, Grounding DINO-T y DETR' },
          { t: 'compare', models: [Y8, C, GD, GD672, DT], rows: ['params', 'macs'], caption: 'YOLOv8-L @ 640, YOLO-World-L @ 640 (sin text encoder), Grounding DINO-T @ 896×1344 (su config del Atlas, T = 16) y @ 672×672 (misma escala que 640), y DETR-R50 @ 640. Calculador; cada uno a la resolución que dice su nombre.' },
          { t: 'p', html: R`Lectura: YOLO-World-L cuesta por imagen ${qn('metrics.macsVsYolov8')} veces un YOLOv8-L. Grounding DINO-T en su configuración del Atlas (${qn('label', GD)}) cuesta ${qn('metrics.gdinoToYoloWorldMacs')} veces los MACs de YOLO-World-L, pero esa cifra mezcla arquitectura y resolución: 896×1344 tiene casi tres veces los píxeles de 640×640. A escala parecida, ${qn('label', GD672)} cuesta ${qn('macs.totalG', GD672)} MACs, ${qn('metrics.gdino672ToYoloWorldMacs')} veces YOLO-World-L, y a 448×448 cuesta ${qn('macs.totalG', 'grounding-dino-t-448')} MACs, prácticamente lo mismo que YOLO-World-L (${qn('macs.totalG')}). Además, no tiene un modo "vocabulario precompilado": BERT y la fusión corren con cada imagen.` },
          { t: 'callout', kind: 'trap', title: '"La diferencia de MACs explica la de FPS"', html: R`<p>No. La Tabla 2 del paper mide 52.0 FPS para YOLO-World-L y 1.5 para Grounding DINO-T en la misma V100 sin TensorRT: unas 35 veces. A resolución parecida, los MACs difieren ${qn('metrics.gdino672ToYoloWorldMacs')} veces. El resto es <b>cómo corre</b> cada uno: YOLO-World son convs densas que la GPU ejecuta cerca de su pico; Grounding DINO hace gathers irregulares en la atención deformable (limitados por memoria, no por cómputo), la selección de queries en dos etapas (top-k por imagen y después el decoder), BERT por imagen, seis capas de decoder en secuencia, decenas de kernels chicos y mucho tráfico de activaciones sobre decenas de miles de tokens. Y la medición pesa: el propio paper de Grounding DINO reporta 8.37 FPS para el mismo modelo (su Tabla 20, sin decir GPU ni resolución). Compara siempre en el mismo hardware, runtime, precisión y resolución.</p>` },
        ],
      },

      // ======================================================== 6
      {
        id: 'entrenamiento',
        titleEn: 'Training',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`La idea central de entrenamiento: <b>todo se convierte en pares región-texto</b> (§3.1). Una anotación de detección (caja, "person") es un par; una de grounding (caja, "the man in a red shirt") también; un par imagen-caption de la web se convierte en pares con pseudo-etiquetas. Con eso, una sola pérdida sirve para los tres tipos de datos.` },
          { t: 'math', display: true, tex: R`\mathcal L(I) = \mathcal L_\text{con} + \lambda_I\cdot\big(\mathcal L_\text{iou} + \mathcal L_\text{dfl}\big),\qquad \lambda_I = \begin{cases}1 & I\ \text{de detección o grounding}\\ 0 & I\ \text{de imagen-texto (pseudo-etiquetas)}\end{cases}`, caption: 'Pérdida total (§3.4). Las cajas de las pseudo-etiquetas son ruidosas: solo enseñan "qué", no "dónde".' },
          { t: 'p', html: R`\(\mathcal L_\text{con}\) es la "pérdida contrastiva región-texto": TAL asigna los puntos de anclaje positivos a cada objeto (igual que en YOLOv8), cada positivo recibe como etiqueta el <b>índice de su texto</b> en el vocabulario del mosaico, y la pérdida compara los logits región-texto con esa asignación. El paper la describe como entropía cruzada; en el código oficial (mmyolo) es la misma <b>BCE con sigmoide por clase</b> de YOLOv8, con los objetivos suaves de TAL (la puntuación alineada, no un 1 duro). No hay negativos "del batch" como en CLIP: los negativos son las otras palabras del vocabulario del mosaico.` },
          { t: 'math', display: true, tex: R`\mathcal L_\text{con} = \frac{1}{\sum t}\sum_{k}\sum_{j=1}^{V}\mathrm{BCE}\big(\sigma(s_{k,j}),\ t_{k,j}\big),\qquad t_{k,j} = \begin{cases}\text{puntuación alineada de TAL} & k\ \text{positivo de un objeto con texto } j\\ 0 & \text{si no}\end{cases}`, caption: 'Cómo la implementa el código oficial (YOLOWorldHead.loss_by_feat, con la BCE de YOLOv8 de mmyolo): sigmoide por par (punto, palabra), normalizada por la suma de los objetivos.' },
          { t: 'kv', items: [
            ['Vocabulario por muestra', 'Online: por cada mosaico de 4 imágenes, todas las palabras positivas + negativas muestreadas al azar del dataset, hasta M = 80 (§3.2). El repo rellena hasta 80 con cadenas vacías (<code>padding_value=\'\'</code> en la config)', '§3.2, configs del repo'],
            ['Text encoder', 'CLIP (ViT-B/32 en el código), congelado en el preentrenamiento', '§4.2, Tabla 5'],
            ['Optimizador', 'AdamW, LR 2·10⁻³, weight decay 0.05', '§4.2'],
            ['Épocas y batch', '100 épocas en 32 V100, batch total 512', '§4.2'],
            ['Augmentation', 'color, random affine, flip y mosaico de 4 imágenes (como YOLOv8)', '§4.2'],
            ['Pérdida de caja', 'IoU (CIoU en el código) + DFL, solo con cajas confiables (λ_I)', '§3.4'],
            ['Asignación', 'Task-Aligned (TAL, de TOOD), igual que YOLOv8', '§3.4'],
            ['Fine-tuning (COCO, LVIS)', '80 épocas, AdamW, LR 2·10⁻⁴; el text encoder se fine-tunea con LR × 0.01', '§4.4, A.2'],
          ] },
          { t: 'h3', text: 'Datos: detección, grounding y pseudo-etiquetas' },
          { t: 'table', caption: 'Datos de preentrenamiento (Tabla 1 del paper)', head: ['Dataset', 'Tipo', 'Vocabulario', 'Imágenes', 'Anotaciones'], rows: [
            ['Objects365 V1', 'Detección', '365 clases', '609k', '9,621k'],
            ['GQA', 'Grounding', 'frases', '621k', '3,681k'],
            ['Flickr30k', 'Grounding', 'frases', '149k', '641k'],
            ['CC3M† (pseudo-etiquetado)', 'Imagen-texto', 'frases', '246k', '821k'],
          ], note: 'GoldG = GQA + Flickr30k, sin las imágenes de COCO (siguiendo a GLIP), §4.2. † = el subconjunto de CC3M que los autores etiquetaron con su pipeline.' },
          { t: 'steps', items: [
            { title: '1. Frases nominales', html: R`<p>De cada caption de CC3M se extraen frases nominales con un algoritmo simple de n-gramas.</p>` },
            { title: '2. Cajas con un detector abierto', html: R`<p>GLIP-L propone cajas para esas frases, con una confianza c<sub>i</sub>: pares región-texto "gruesos" (Apéndice B, ec. 7).</p>` },
            { title: '3. Re-puntuar con CLIP', html: R`<p>Se recorta cada caja y CLIP mide la similitud región-frase \(s^r_i\); la confianza nueva es \(\tilde c_i = \sqrt{c_i\cdot s^r_i}\). Opcional: re-etiquetar cada recorte con la frase de mayor similitud (corrige errores de GLIP).</p>` },
            { title: '4. Filtrar regiones', html: R`<p>NMS por frase con IoU 0.5 y umbral de confianza 0.3.</p>` },
            { title: '5. Filtrar imágenes', html: R`<p>Puntuación de imagen \(s = \sqrt{s^{img}\cdot s^{region}}\) (similitud imagen-caption por la media de las regiones que quedaron); se quedan las imágenes con s &gt; 0.3. Todo automático, sin verificación humana: 246k imágenes y 821k anotaciones.</p>` },
          ] },
          { t: 'callout', kind: 'senior', title: 'Qué dicen las ablaciones (lo que un entrevistador anota)', html: R`<p><b>Datos con texto rico pesan más que la arquitectura.</b> Tabla 3: preentrenar con O365 + GQA en vez de solo O365 sube +8.4 AP zero-shot en LVIS (23.5 → 31.9); el CC3M pseudo-etiquetado (246k imágenes: ≈ 15 % de las imágenes y 5.6 % de las anotaciones de la Tabla 1) suma +0.5 AP y +1.3 en raras. Tabla 4: RepVL-PAN completo suma +1.1 AP sobre el PAN de YOLOv8 con O365 (22.4 → 23.5), y +2.2 con GQA (29.7 → 31.9): la fusión rinde más cuando el texto es rico. Tabla 5: CLIP congelado le gana a BERT por 7.8 AP, y fine-tunear CLIP lo empeora. Apéndice C: en el modelo S, demasiadas pseudo-etiquetas pueden <i>bajar</i> el AP total (O365 + CC3M-520k da 19.2, con 750k baja a 18.2), mientras que GoldG (anotación humana fina) da 24.2: calidad &gt; cantidad para modelos chicos.</p>` },
          { t: 'h3', text: 'Qué número citar' },
          { t: 'table', caption: 'Zero-shot en LVIS minival, Fixed AP (Tabla 2 del paper; FPS en una V100 sin TensorRT)', head: ['Modelo', 'Backbone', 'Params', 'Datos', 'FPS', 'AP', 'AP<sub>r</sub>'], rows: [
            ['GLIP-T', 'Swin-T', '232M', 'O365, GoldG, Cap4M', '0.12', '26.0', '20.8'],
            ['Grounding DINO-T', 'Swin-T', '172M', 'O365, GoldG, Cap4M', '1.5', '27.4', '18.1'],
            ['DetCLIP-T', 'Swin-T', '155M', 'O365, GoldG', '2.3', '34.4', '26.9'],
            ['YOLO-World-S', 'YOLOv8-S', '13M (77M)', 'O365, GoldG', '74.1 (19.9)', '26.2', '19.1'],
            ['YOLO-World-M', 'YOLOv8-M', '29M (92M)', 'O365, GoldG', '58.1 (18.5)', '31.0', '23.8'],
            ['YOLO-World-L', 'YOLOv8-L', '48M (110M)', 'O365, GoldG', '52.0 (17.6)', '35.0', '27.1'],
            ['YOLO-World-L', 'YOLOv8-L', '48M (110M)', 'O365, GoldG, CC3M†', '52.0 (17.6)', '35.4', '27.6'],
          ], note: 'Tabla 2 de Cheng et al. (arXiv v3). Sin paréntesis: versión re-parametrizada (sin text encoder); entre paréntesis: versión original, con el text encoder en el forward. Fixed AP: hasta 10,000 detecciones por clase en el dataset, sin tope por imagen (Dave et al., 2021); el modelo da hasta 1000 predicciones por imagen (§4.2).' },
          { t: 'callout', kind: 'trap', title: '"35.4 AP" sin contexto', html: R`<p>Es <b>Fixed AP en LVIS minival</b> (5k imágenes), zero-shot: sin el tope habitual de 300 detecciones por imagen y, en su lugar, hasta 10,000 detecciones por clase en todo el dataset (Dave et al., 2021). Aparte, el modelo se configura para dar hasta 1000 predicciones por imagen (§4.2); ese 1000 no es lo que define "Fixed". No es el AP estándar de LVIS val completo ni el de COCO. Los modelos del repo cambiaron de versión (v2, v2.1) y reportan otras cifras en otras particiones: cita tabla, partición y versión. Y el 52.0 FPS es sin el text encoder, en V100 y sin TensorRT; con el text encoder en el forward, 17.6.</p>` },
        ],
      },

      // ======================================================== 7
      {
        id: 'inferencia',
        titleEn: 'Inference',
        priority: 'core',
        blocks: [
          { t: 'steps', items: [
            { title: 'Offline: definir y codificar el vocabulario', html: R`<p>Escribes la lista de clases (palabras o frases cortas). CLIP las codifica una vez: ${sh('vocab')}. En Ultralytics, <code>model.set_classes(["person", "forklift"])</code> hace esto y guarda los embeddings dentro del modelo.</p>` },
            { title: 'Offline: re-parametrizar', html: R`<p>Los embeddings normalizados (× α) pasan a ser los pesos de las convs 1×1 de la cabeza (V filas por nivel) y de las max-sigmoid de los T-CSPLayers (Apéndice A.1). El modelo resultante es un YOLO de V clases, sin text encoder (en el repo: <code>tools/reparameterize_yoloworld.py</code>). Es exacto en la v2; en la v1, los T-CSPLayers del camino bottom-up reciben el texto que la image-pooling attention actualizó con cada imagen, así que esa parte no se puede plegar en pesos fijos.</p>` },
            { title: 'Online: una pasada', html: R`<p>Letterbox a 640×640, backbone → RepVL-PAN → cabeza: ${sh('logits-p3')} + ${sh('logits-p4')} + ${sh('logits-p5')} logits y las cajas DFL de los ${qn('quantities.anchors')} puntos.</p>` },
            { title: 'Online: post-proceso', html: R`<p>Sigmoide, umbral de confianza, <b>NMS</b> (IoU 0.7 por defecto, multi-etiqueta en mmyolo: un punto puede dar dos clases) y top-k. Igual que YOLOv8.</p>` },
          ] },
          { t: 'h3', text: 'Qué domina la latencia' },
          { t: 'p', html: R`A 640×640 con V = ${cV()}: el backbone se lleva ${npc('backbone')} de los MACs, el neck ${npc('neck')} y las cabezas ${npc('head-box')} + ${npc('head-text')}. Todo son convoluciones (más una atención diminuta de 27 claves en la v1): exporta y se fusiona como un YOLO. El text encoder no aparece en inferencia, salvo que cambies el vocabulario. Lo que sí cambia frente a YOLOv8: NMS con vocabularios grandes (más candidatas sobre el umbral) y, si mantienes la versión no re-parametrizada, las operaciones de normalización y einsum que algunos runtimes optimizan peor (con opset 11, que no tiene einsum, el repo indica subir a opset 12 o poner <code>use_einsum=False</code> en la config; trae una config de ejemplo sin einsum, docs/deploy.md).` },
          { t: 'p', html: R`<b>En un Jetson Orin</b> el backbone sigue mandando en la red, pero aparecen costos que en una V100 no se ven: (1) el <b>preprocesado</b> (letterbox, normalización, HWC → CHW) si lo haces en la CPU ARM en vez de en la GPU; (2) <b>NMS</b> y la decodificación de cajas: mejor dentro del motor (el plugin EfficientNMS de TensorRT o NMS en GPU) que en Python en la CPU; (3) con vocabularios grandes, el top-k sobre ${qn('quantities.anchors')} × V puntuaciones; (4) el ancho de banda de memoria, mucho menor que el de una GPU de servidor, que castiga las activaciones grandes de P3 a alta resolución. A favor: el modelo re-parametrizado es todo convs, así que va a FP16 o INT8 como un YOLO y puede repartirse entre la GPU y los DLA del Orin. ${est('Mide red, NMS y preprocesado por separado (trtexec para el motor, Nsight Systems para el pipeline, batch 1, p99): los FPS de una V100 no se trasladan')}.` },
          { t: 'callout', kind: 'senior', title: 'Re-parametrizar no es opcional en edge', html: R`<p>Sin re-parametrizar, cada forward hace: L2-norm de los ${qn('quantities.anchors')} embeddings, L2-norm del vocabulario, un einsum contra el vocabulario en cada nivel y en cada T-CSPLayer. Re-parametrizado: convs 1×1 con los pesos fijos, que TensorRT fusiona con lo de alrededor. La v2 fue más lejos por esa razón: (1) quitó la image-pooling attention, porque hacía que el vocabulario dependiera de la imagen; (2) cambió la L2-norm de la cabeza por BatchNorm, que se pliega en la conv (el repo dice que la L2 tiene "reduce" costosos en deploy y que BN además mejora el zero-shot). Ultralytics lo refleja: sus modelos v1 no se pueden exportar; los <code>-worldv2</code> sí (ONNX, TensorRT y los demás formatos de export), con el vocabulario fijado al exportar.</p>` },
          { t: 'table', head: ['Truco', 'Qué hace', 'Cuándo importa'], rows: [
            ['Vocabulario mínimo', 'Solo las clases que el sistema necesita: menos canales en la cabeza, menos falsos positivos y menos trabajo de NMS', 'Siempre en producción'],
            ['Re-parametrizar y exportar (v2)', 'Pesos de texto dentro de las convs; ONNX/TensorRT sin text encoder', 'Edge, latencia fija'],
            ['Cambiar el vocabulario en caliente', 'Mantener CLIP en el servidor y recodificar solo cuando cambia la lista (milisegundos por palabra en GPU); en edge, re-exportar o mantener la versión con einsum', 'Robots con tareas cambiantes'],
            ['Resolución 1280', 'Checkpoints del repo con preentrenamiento continuado a 1280: mejor en chicos, ×4 MACs', 'Objetos chicos, cámaras de alta resolución'],
            ['INT8', 'Todo es conv: cuantiza como un YOLO; el repo documenta export a TFLite INT8 (quitar NMS y el decodificador de cajas del grafo antes de cuantizar)', 'Jetson, móviles'],
            ['Fine-tuning re-parametrizado', 'Entrenar sobre la versión con el vocabulario plegado: neck y cabeza se ajustan sin depender del texto', 'Vocabulario fijo con datos propios'],
          ] },
          { t: 'callout', kind: 'trap', title: '"Con prompt-then-detect, YOLO-World ya no necesita NMS"', html: R`<p>No: prompt-then-detect elimina el text encoder del camino online, no la NMS. La salida sigue siendo densa (una predicción por punto, varios positivos por objeto en entrenamiento), así que los duplicados existen y NMS los limpia. Para un YOLO abierto sin NMS habría que cambiar la asignación, como hace YOLOv10 con su cabeza uno a uno (el porqué, en <a href="#detr.puente">DETR</a>).</p>` },
        ],
      },

      // ======================================================== 8
      {
        id: 'fallas',
        titleEn: 'Failure modes and trade-offs',
        priority: 'core',
        blocks: [
          { t: 'list', ordered: true, items: [
            R`<b>Ambigüedad del vocabulario.</b> "bat" (murciélago o bate), "glass" (vaso o vidrio), "mouse". El embedding de CLIP de una palabra sola mezcla sus sentidos y el detector se equivoca de forma consistente. Mitigación: frases desambiguadas ("baseball bat"), sinónimos agrupados (varias frases que mapean a la misma clase de salida) y, en v1, la image-pooling attention ayuda algo porque adapta el texto a la imagen.`,
            R`<b>Cola larga y palabras raras.</b> El AP en clases raras de LVIS es bastante menor que en frecuentes (APr 27.6 vs APf 38.0 para la L, Tabla 2). Jerga industrial, códigos de producto o nombres propios no están bien representados en CLIP. Y las clases muy parecidas entre sí ("screw" vs "bolt": el vocabulario se escribe en inglés, como lo vio CLIP) compiten: con sigmoide por clase, ambas pueden salir altas.`,
            R`<b>Sensibilidad al prompt.</b> "person" vs "a person" vs "pedestrian" dan detecciones distintas; el plural, las mayúsculas y la longitud importan. Además, el vocabulario completo cambia los resultados: el T-CSPLayer toma el máximo sobre todas las palabras, así que <b>agregar una palabra puede cambiar las features</b> de todas las posiciones, y con ellas las detecciones de las otras clases. (En la cabeza, en cambio, cada logit es independiente.) El repo también documenta un efecto del relleno: el modelo se entrenó con vocabularios rellenados con cadenas vacías hasta 80, y con pocas clases suele hacer falta agregar ese relleno para obtener resultados razonables (nota de la v2.1).`,
            R`<b>Objetos chicos y escenas densas.</b> Los mismos límites que YOLOv8 a 640: P3 tiene stride 8. Las versiones a 1280 ayudan. Además, la fusión con texto es liviana y un objeto chico tiene pocas posiciones para "encenderse" en la max-sigmoid.`,
            R`<b>Fine-tuning cerrado que mata el vocabulario abierto.</b> Si fine-tuneas todo sobre tus 5 clases, el detector se especializa y pierde zero-shot. El paper lo mide en segmentación (Tabla 8): fine-tunear todos los módulos en LVIS-base sube 9.6 AP de máscara pero baja 0.6 el AP de caja en clases raras (18.0 → 17.4); fine-tunear solo la cabeza de segmentación conserva el zero-shot. Y para COCO quitan RepVL-PAN del todo (Tabla 6): queda un YOLOv8 preentrenado, rápido, pero ya no abierto.`,
          ] },
          { t: 'callout', kind: 'senior', title: 'Fine-tunear en tus clases sin matar el vocabulario abierto', html: R`<p>Opciones, de menos a más invasiva: (1) <b>solo prompts</b>: ajustar las frases (y agrupar sinónimos) sin entrenar; (2) <b>prompt tuning</b>: aprender los embeddings de tus clases (filas del vocabulario) con todo lo demás congelado: las demás clases no cambian; (3) fine-tuning con <b>vocabulario mixto</b>: tus clases más negativos muestreados de un vocabulario grande (como el entrenamiento original) y LR bajo, para que el detector no aprenda que "todo es una de mis 5 clases"; (4) mezclar en cada batch datos de preentrenamiento (O365/GoldG) con los tuyos (replay); (5) si no necesitas vocabulario abierto, fine-tuning re-parametrizado o sin RepVL-PAN: lo más rápido, pero cerrado. Evalúa siempre dos cosas: mAP en tus clases <b>y</b> zero-shot en un set de clases que no entrenaste (p. ej. LVIS minival).</p>` },
          { t: 'table', caption: 'YOLO-World vs alternativas (filas = criterios)', head: ['Criterio', 'YOLOv8 (cerrado)', 'YOLO-World', 'Grounding DINO', 'OWLv2', 'YOLOE'], rows: [
            ['Clases', 'Fijas al entrenar', 'Vocabulario de texto, re-parametrizable', 'Texto libre por imagen (frases, expresiones)', 'Texto o imagen de ejemplo por imagen', 'Texto, prompt visual o sin prompt'],
            ['Fusión imagen-texto', 'No hay', 'Liviana: max-sigmoid en el neck + producto punto en la cabeza', 'Profunda: enhancer de 6 capas, selección de queries guiada por texto, decoder con cross-attention al texto', 'Tardía: ViT de imagen y producto punto por token con los embeddings de clase', 'Solo en la cabeza (RepRTA re-parametrizable), sin fusión en el neck'],
            ['Text encoder por imagen', '—', 'No (offline)', 'Sí (BERT)', 'No si el vocabulario es fijo (embeddings cacheados)', 'No (offline)'],
            ['Arquitectura de detección', 'Densa, TAL, NMS', 'Densa, TAL, NMS', 'DETR (DINO): queries, húngaro, sin NMS', 'Una caja por token del ViT (ViT sin decoder)', 'Densa, como YOLOv8 / YOLO11'],
            ['Velocidad', 'La más alta', '52.0 FPS (L, V100, Tabla 2)', '1.5 FPS (T, V100, Tabla 2 de YOLO-World)', 'Lenta a alta resolución (ViT-B/16 a 960, L/14 a 1008)', 'Su abstract: 1.4× más rápido que YOLO-Worldv2-S (afirmación relativa del paper)'],
            ['Precisión zero-shot (LVIS)', '—', 'Buena para su tamaño (35.4 AP minival, L)', 'En LVIS minival, por debajo de YOLO-World-L (27.4 la T, 33.9 la L, Tabla 3 de su paper); mejor en COCO zero-shot (48.4 / 52.5 frente a 45.1 de YOLO-World-L, Tabla 6 de YOLO-World) y con frases referenciales', 'Muy alta en raras (L/14 con OWL-ST: 44.6 AP<sub>r</sub>, abstract del paper)', 'Paper: +3.5 AP sobre YOLO-Worldv2-S (con el modelo S)'],
            ['Cuándo elegirlo', 'Clases fijas, datos propios', 'Tiempo real con vocabulario conocido por sesión', 'Grounding de frases con atributos o relaciones, prompts que cambian por imagen, etiquetado offline', 'Calidad en clases raras, prompts por imagen de ejemplo', 'Tiempo real con prompts visuales o sin prompt; también segmenta'],
          ], note: 'Grounding DINO: Liu et al., ECCV 2024, arXiv:2303.05499. OWLv2: Minderer et al., NeurIPS 2023, arXiv:2306.09683. YOLOE: Wang et al., ICCV 2025, arXiv:2503.07465 (cifras de su abstract). Los FPS de distintos papers no se comparan entre sí: GPU, precisión y runtime cambian.' },
          { t: 'callout', kind: 'interview', html: R`<p>"YOLO-World trades fusion depth for speed: text only modulates the neck through a cheap max-sigmoid gate and becomes 1×1 conv weights in the head, so per-image cost is a YOLO's. It works well for category names but is weaker than Grounding DINO on long referring expressions, it inherits CLIP's blind spots on domain jargon and ambiguous words, results depend on the exact prompt and the rest of the vocabulary, and it still needs NMS."</p>` },
        ],
      },

      // ======================================================== 9
      {
        id: 'variantes',
        titleEn: 'Variants and descendants',
        priority: 'extra',
        blocks: [
          { t: 'table', head: ['Modelo o versión', 'Qué cambia (una línea)', 'Dónde lo ves'], rows: [
            ['YOLO-World v1 (el paper)', 'RepVL-PAN con T-CSPLayers e image-pooling attention; cabeza con L2-norm. Tamaños S, M, L (y X en el repo).', 'Esta página'],
            ['YOLO-World v2 (repo, 2024-02-29)', R`Sin image-pooling attention (complicaba la velocidad tras exportar) y BatchNorm en lugar de L2-norm en la cabeza contrastiva (se pliega en la conv); el repo reporta más precisión y velocidad. La L queda en ${qn('quantities.v2Params')} parámetros (calculador; frente a ${qn('params.total')} de la v1).`, R`${REPO}, docs/updates.md`],
            ['YOLO-World a 1280, con CLIP-Large, YOLO-World-Seg (repo, 2024)', 'Preentrenamiento continuado a 1280 para objetos chicos; text encoder CLIP-L; una cabeza de máscaras para segmentación de vocabulario abierto.', 'Repo oficial'],
            ['YOLO-World v2.1 y YOLO-World-Image (repo, 2025-02)', 'Máscara para el relleno del vocabulario en la pérdida, datos re-etiquetados con RAM++, y prompts visuales: el encoder de imagen de CLIP más un adaptador MLP reemplaza al embedding de texto.', 'Repo oficial, docs/update_20250123.md'],
            ['Ultralytics YOLO-World (<code>yolov8*-world</code>, <code>yolov8*-worldv2</code>)', 'Mismos pesos migrados del repo oficial; <code>set_classes</code> codifica con CLIP ViT-B/32 y guarda el vocabulario; solo los v2 exportan. Entrenamiento "desde cero" experimental.', 'docs.ultralytics.com'],
            ['YOLOE (Wang et al., ICCV 2025, arXiv:2503.07465)', 'Texto con RepRTA (una red auxiliar re-parametrizable refina los embeddings de texto: costo cero en inferencia, sin fusión en el neck), prompts visuales (SAVPE) y modo sin prompt (LRPC con un vocabulario interno grande); detecta y segmenta.', 'Sucesor directo en tiempo real'],
            ['YOLO-UniOW (Liu et al., arXiv:2412.20645)', 'Quita la fusión en el neck y alinea solo en el espacio de CLIP ("Adaptive Decision Learning"); agrega una clase comodín para detectar objetos "desconocidos" (open-world).', '—'],
            ['OWL-ViT (Minderer et al., ECCV 2022, arXiv:2205.06230) y OWLv2 (NeurIPS 2023, arXiv:2306.09683)', 'ViT de CLIP con una caja y un embedding por token de salida; OWLv2 escala con auto-entrenamiento sobre pares web (OWL-ST).', '—'],
            ['GLIP (Li et al., CVPR 2022, arXiv:2112.03857)', 'Detección como grounding de frases con fusión profunda; es el etiquetador que YOLO-World usa para pseudo-etiquetar CC3M.', R`Antecesor de <a href="#grounding-dino">Grounding DINO</a>`],
            ['Grounding DINO (Liu et al., ECCV 2024, arXiv:2303.05499)', 'DETR (DINO) con fusión texto-imagen en encoder, selección de queries y decoder: el extremo "fusión profunda" (caro por imagen; gana en COCO y con frases, no en LVIS zero-shot).', R`<a href="#grounding-dino">Grounding DINO</a>`],
          ] },
          { t: 'callout', kind: 'skip', html: R`<p><b>Sáltate esto</b> si vas corto: los detalles de v2.1 (relleno, RAM++) y de YOLO-UniOW. Lo que se pregunta es la idea de v2 (quitar lo que no se re-parametriza) y el contraste con Grounding DINO y YOLOE.</p>` },
        ],
      },

      // ======================================================== 10
      {
        id: 'entrevista',
        titleEn: 'Interview questions',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`YOLO-World sale en entrevistas de visión y robótica como "el detector abierto que sí corre en tiempo real". Lo que se evalúa es si entiendes qué cambia respecto de YOLO (y qué no), qué compra la re-parametrización y cuándo elegirlo frente a Grounding DINO. Preguntas en inglés como las hace el entrevistador; respuestas en español, con la frase senior en inglés.` },
          { t: 'followups', items: [
            { q: 'Walk me through YOLO-World starting from YOLOv8. What exactly changes?',
              junior: 'Le agregan CLIP a YOLO para que entienda texto.',
              senior: R`Backbone, PAN, rama de caja (DFL + CIoU), asignación TAL y NMS: iguales. Cambian tres cosas. (1) La rama de clase termina en un object embedding de ${cE()} por punto (${sh('obj-emb-p3')} en P3) en vez de K logits, y el logit es un coseno escalado con el embedding de texto de cada palabra: \(s = \alpha\,\hat e\cdot\hat w + \beta\) → ${sh('logits-p3')}. (2) El neck es RepVL-PAN: cada C2f pasa a ser un T-CSPLayer con max-sigmoid attention (texto → imagen), y en la v1 una image-pooling attention actualiza el texto con 27 tokens de imagen. (3) Se preentrena en datos región-texto (O365, GoldG, CC3M pseudo-etiquetado) con el text encoder de CLIP congelado. En inferencia el vocabulario se codifica offline y se pliega en pesos.`,
              say: 'Backbone, PAN, the DFL box branch, task-aligned assignment and NMS stay the same. The classification branch outputs a 512-dimensional object embedding per anchor point, and class logits are scaled cosine similarities with CLIP text embeddings; the neck gets text-guided CSP layers; and it is pre-trained on region-text pairs with a frozen CLIP text encoder.',
              why: 'La pregunta de entrada. Se anota que sepas qué NO cambia (TAL, DFL, NMS) tanto como qué cambia.' },
            { q: 'How do you add a new class at deploy time?',
              junior: 'Reentreno la cabeza con imágenes de la clase nueva.',
              senior: R`Sin reentrenar: escribo la palabra, la codifico con el text encoder de CLIP y agrego esa fila al vocabulario. En la versión re-parametrizada eso es agregar un canal de salida a la conv 1×1 de la cabeza (y una fila a las convs de las max-sigmoid) y re-exportar; en la versión con einsum, basta con pasar el vocabulario nuevo. Matices que se anotan: (1) en la cabeza, los logits de las clases viejas no cambian (cada fila es independiente), pero en el neck sí puede cambiar todo, porque la max-sigmoid toma el máximo sobre el vocabulario completo; (2) si exporté a TensorRT con V fijo, el motor se reconstruye; (3) primero valido el zero-shot en un set chico de la clase nueva: si CLIP no conoce la palabra, toca prompt tuning o fine-tuning.`,
              say: 'I encode the new class name with the CLIP text encoder and append it to the vocabulary, which in the re-parameterized model means adding an output channel to the 1×1 conv weights and re-exporting. Old class logits in the head do not change, but the max-sigmoid gate in the neck takes a max over the whole vocabulary, so I validate on a few images first.',
              why: 'Trampa: "reentreno". Lo que se anota es la fila nueva, la re-exportación y el efecto del máximo en el neck.', trap: true },
            { q: 'What does re-parameterization buy you, concretely?',
              junior: 'Hace el modelo más chico.',
              senior: R`Saca el text encoder del camino por imagen y convierte operaciones dependientes del texto en convs con pesos fijos. Concretamente: (1) el text encoder (${tP} parámetros de CLIP) ya no corre ni se despliega: el paper pasa de 110M a 48M parámetros y de 17.6 a 52.0 FPS en la L (Tabla 2); (2) normalizar y transponer el vocabulario en cada forward se reemplaza por una conv 1×1 de pesos \(\alpha\hat w_j\), que los compiladores fusionan; (3) con la cabeza BN de la v2, la normalización de la imagen también se pliega y la cabeza entera es una conv; (4) el grafo exportado es un YOLO normal: ONNX, TensorRT, INT8 como siempre. Lo que <b>no</b> compra: no quita NMS, no cambia la precisión (es la misma función) y fija el vocabulario en el artefacto exportado. Repregunta segura, "what exactly becomes weights in v1?": la cabeza y los T-CSPLayers top-down se pliegan del todo; los bottom-up reciben el texto que la image-pooling attention actualiza con cada imagen, así que ahí no hay un peso fijo que escribir (el apéndice re-parametriza esa atención, ec. 5–6, pero sigue dependiendo de la imagen). Por eso la v2 la quitó y Ultralytics no exporta la v1.`,
              say: 'It removes the text encoder from the per-image path and turns text-dependent operations into fixed 1×1 conv weights: the deployed model is a plain YOLO with V output channels, which exports and fuses normally. In the paper that is 48 versus 110 million parameters and 52 versus 17.6 FPS for the large model. It computes the same function, so accuracy is unchanged, and it does not remove NMS. In v1 the bottom-up text-guided layers still see image-dependent text, so only v2 folds completely.',
              why: 'Se anota: misma función (no es una aproximación), qué se pliega, los números de la Tabla 2 y que no quita NMS.' },
            { q: 'Why does YOLO-World still need NMS when DETR-style detectors don\'t?',
              junior: 'Porque no tiene transformer.',
              senior: R`Porque se entrena con la asignación de YOLOv8: TAL da varios positivos por objeto (los top-k puntos por la métrica alineada), así que, según su propia pérdida, varios puntos <i>deben</i> predecir el mismo objeto. Eso garantiza duplicados en inferencia, y NMS los limpia. DETR (y YOLOv10 con su cabeza uno a uno) cambian la asignación a uno a uno con un costo que incluye la clase; lo que elimina NMS es eso, no el transformer ni el texto. Prompt-then-detect tampoco tiene nada que ver: quita el text encoder del camino online, no la NMS. Detalle: el post-proceso de mmyolo es multi-etiqueta, así que la misma caja puede salir con dos palabras ("car" y "vehicle"); NMS por clase no las fusiona, y conviene agrupar sinónimos.`,
              say: 'Because it is trained with YOLOv8\'s one-to-many task-aligned assignment, so several anchor points are supposed to fire for each object and duplicates are expected. What removes NMS is one-to-one assignment with a class-aware cost, as in DETR or YOLOv10, not attention or text. Prompt-then-detect removes the text encoder from inference, not NMS.',
              why: 'Trampa: atribuir NMS a "no tener transformer" o creer que prompt-then-detect lo elimina.', trap: true },
            { q: 'Where does CLIP come in, and what does it cost at inference?',
              junior: 'CLIP procesa cada imagen junto con el texto.',
              senior: R`Solo el <b>text encoder</b> de CLIP (ViT-B/32 en el código: el transformer de texto de {{clip-vit-b32.cfg.Lt}} capas, ${tP} parámetros); el encoder de imagen de CLIP no se usa (salvo en las variantes con prompts visuales). Codifica cada palabra del vocabulario en un vector de ${cE()}. En inferencia cuesta <b>cero por imagen</b>: corre una vez cuando defines el vocabulario (${tM} MACs por palabra con los 77 tokens de Ultralytics, el peor caso; el repo oficial rellena solo hasta el nombre más largo y cuesta bastante menos; ${est('milisegundos para decenas de palabras en una GPU')}). Además, CLIP se usa en el pipeline de datos (re-puntuar pseudo-etiquetas). Por qué CLIP y no BERT: Tabla 5, 22.4 vs 14.6 AP congelados; CLIP aprendió texto alineado con imágenes.`,
              say: 'Only CLIP\'s text encoder is used, to turn each vocabulary entry into a 512-dimensional embedding. It runs once per vocabulary, not per image, so after re-parameterization it costs nothing at inference time. The image tower of CLIP is not part of the detector; CLIP is also used offline to rescore pseudo-labels.',
              why: 'Trampa: creer que CLIP procesa la imagen. Se anota: solo la torre de texto, una vez por vocabulario.', trap: true },
            { q: 'YOLO-World or Grounding DINO for a robot on a Jetson?',
              junior: 'Grounding DINO porque es más preciso.',
              senior: R`YOLO-World (v2, re-parametrizado y exportado a TensorRT), salvo que el robot necesite entender frases referenciales. Razones: (1) costo por imagen: el detector de YOLO-World-L cuesta ${qn('macs.totalG')} MACs a 640; Grounding DINO-T a escala parecida (${qn('label', GD672)}) cuesta ${qn('macs.totalG', GD672)}, ${qn('metrics.gdino672ToYoloWorldMacs')} veces más, con BERT y la fusión en cada imagen. Pero la latencia difiere mucho más que los MACs: en V100 el paper mide 52.0 vs 1.5 FPS (Tabla 2), unas 35 veces, por la atención deformable limitada por memoria, el decoder secuencial y BERT por imagen; (2) export: YOLO-World v2 es convs (TensorRT, INT8 como un YOLO), mientras que Grounding DINO lleva atención deformable, BERT y máscaras de texto; (3) el vocabulario de un robot cambia por tarea, no por frame: precompilarlo encaja. Cuándo Grounding DINO: instrucciones del tipo "la taza roja junto al teclado", o etiquetado offline donde la latencia no importa (ahí también lo usaría para generar datos y después fine-tunear un YOLO). No lo elijo "por precisión" sin medir: en LVIS zero-shot YOLO-World-L le gana (35.4 vs 27.4 de la T); Grounding DINO gana en COCO y con frases. Lo mediría: p99 en el Jetson real, con mi vocabulario y mis escenas.`,
              say: 'For a Jetson I would deploy a re-parameterized YOLO-World v2 through TensorRT: its per-image cost is a YOLO\'s and the vocabulary changes per task, not per frame. Grounding DINO is only about twice the MACs at a similar resolution, but tens of times slower in practice because of deformable attention, a sequential decoder and per-image BERT, and it is harder to export, so I would use it offline for labeling or when I need real referring-expression grounding, and benchmark p99 latency on the device.',
              why: 'Trampa: "el más preciso" (en LVIS zero-shot no lo es). Lo que se anota es costo por imagen a igual resolución, por qué la latencia difiere más que los MACs, export, y cuándo sí Grounding DINO.', trap: true },
            { q: 'How would you fine-tune on your factory classes without killing open-vocabulary detection?',
              junior: 'Fine-tuneo todo el modelo con mis clases.',
              senior: R`Depende de si necesito el vocabulario abierto después. Si sí: (1) empiezo sin entrenar (prompts y sinónimos) y mido; (2) prompt tuning: aprendo solo los embeddings de mis clases, con el detector congelado; (3) si hace falta más, fine-tuning con LR bajo, vocabulario mixto (mis clases + negativos muestreados de un vocabulario grande, como en el preentrenamiento) y replay de datos de O365/GoldG en cada batch; text encoder congelado (Tabla 5: fine-tunear CLIP sobre pocas categorías lo degrada). Evalúo mAP en mis clases <b>y</b> zero-shot en clases que no entrené. El paper muestra el riesgo: fine-tunear todo en LVIS-base sube 9.6 AP de máscara pero baja 0.6 AP<sub>r</sub> de caja en raras (Tabla 8). Si no necesito vocabulario abierto: fine-tuning re-parametrizado, o sin RepVL-PAN como hacen ellos para COCO; es un YOLOv8 bien inicializado (80 épocas en vez de 300–500).`,
              say: 'If I still need open vocabulary, I try prompts first, then prompt tuning of my class embeddings with the detector frozen, and only then a low learning-rate fine-tune with a mixed vocabulary of my classes plus sampled negatives and replay of pre-training data, keeping CLIP frozen. I track both my-class mAP and zero-shot AP on held-out classes. If I don\'t need it, I fine-tune the re-parameterized model as a well-initialized YOLO.',
              why: 'Trampa: "fine-tuneo todo". Se anota: prompt tuning, vocabulario con negativos, replay, CLIP congelado y medir el zero-shot.', trap: true },
            { q: 'Explain the max-sigmoid attention in the T-CSPLayer. Why max and why sigmoid?',
              junior: 'Es una atención normal entre la imagen y el texto.',
              senior: R`No es una atención con softmax y suma ponderada: no trae contenido del texto. Para cada posición calcula la similitud con las V palabras, toma el <b>máximo</b> y lo pasa por una <b>sigmoide</b>; ese escalar (uno por cabeza en el código) multiplica los canales de la posición. Es un "gate" que enciende las regiones que se parecen a algo del vocabulario y apaga las demás. Máximo: invariante al número y al orden de las palabras (V varía entre entrenamiento e inferencia) y "se parece a <i>alguna</i> clase pedida" es lo que importa para detectar. Sigmoide y no softmax: las posiciones no compiten entre sí, cada una se pondera de forma independiente en (0, 1). Costo: lineal en posiciones × V, sin N². Y con V fijo es una conv 1×1 seguida de un max sobre canales: re-parametrizable. Tabla 4: +0.8 AP en LVIS zero-shot (22.4 → 23.2) preentrenando solo con O365.`,
              say: 'For each spatial position it computes similarities with every vocabulary embedding, takes the maximum and applies a sigmoid, then scales the channels of that position: it is a text-conditioned gate, not attention that mixes text content in. Max makes it independent of vocabulary size and order, sigmoid keeps positions independent, it is linear in pixels times vocabulary, and with a fixed vocabulary it becomes a 1×1 conv plus a channel max.',
              why: 'Se anota que no hay suma ponderada, el porqué del max y de la sigmoide, el costo y que se re-parametriza.', trap: true },
            { q: 'Why L2-normalize the object embeddings and text embeddings, and why the learnable scale and shift?',
              junior: 'Para que los números no sean muy grandes.',
              senior: R`Normalizar convierte el producto punto en un coseno: la clase no puede ganarse por la magnitud del embedding de imagen, y el texto de CLIP (que vive en una esfera) se compara en su escala natural. Pero un coseno está en [−1, 1]: con sigmoide, el logit nunca pasaría de σ(1) ≈ 0.73. La escala α (como el <code>logit_scale</code> de CLIP, inicializada en 1/0.07) estira el rango; el sesgo β pone el logit por defecto muy negativo, porque con BCE por clase casi todos los pares (punto, palabra) son negativos (el código oficial lo inicializa en \(\log(5/V/(640/\text{stride})^2)\), el prior de clase de YOLOv8, "unos 5 objetos por imagen"; no es el prior π = 0.01 de focal loss; Ultralytics usa −10). El paper dice que ambas cosas son importantes para estabilizar el entrenamiento (§3.2). La v2 cambia la L2 de la imagen por BatchNorm: en inferencia se pliega en la conv 1×1 y el repo reporta mejor zero-shot.`,
              say: 'Normalizing turns the dot product into a cosine, so the embedding norm cannot dominate and text is compared on CLIP\'s sphere; but cosines are bounded, so a learnable scale stretches the logits and a learnable bias makes the default very negative, which per-class sigmoid needs when almost every point-word pair is background. Version 2 replaces the image-side L2 norm with BatchNorm, which folds into the conv at inference.',
              why: 'Se anota el límite σ(1) sin α, el porqué del sesgo negativo y la versión BN que se pliega.' },
            { q: 'What is the loss? Is it really contrastive like CLIP?',
              junior: 'Es la InfoNCE de CLIP entre regiones y textos.',
              senior: R`\(\mathcal L = \mathcal L_\text{con} + \lambda_I(\mathcal L_\text{iou} + \mathcal L_\text{dfl})\). "Contrastiva" en el sentido de que el logit es una similitud región-texto y las demás palabras del vocabulario hacen de negativos. Pero no es la InfoNCE simétrica de CLIP: TAL asigna los positivos (igual que YOLOv8), cada positivo toma el índice de su texto como etiqueta, y en el código es la BCE con sigmoide por clase de YOLOv8, con objetivos suaves de TAL. No hay negativos "del batch": el vocabulario de cada mosaico (hasta 80 palabras: positivas + negativas muestreadas) define los negativos. λ_I apaga la pérdida de caja en las pseudo-etiquetas de CC3M porque sus cajas son ruidosas.`,
              say: 'Total loss is a region-text classification term plus IoU and DFL box losses, with the box terms switched off for pseudo-labeled image-text data. It is contrastive only in that logits are region-text similarities and the other words in the sampled vocabulary are negatives; in the official code it is YOLOv8\'s per-class sigmoid BCE with task-aligned soft targets, not CLIP\'s symmetric InfoNCE.',
              why: 'Trampa: decir "InfoNCE de CLIP". Se anota la BCE con TAL, de dónde salen los negativos y λ_I.', trap: true },
            { q: 'How were the image-text data turned into detection labels, and what can go wrong?',
              junior: 'Usan las captions como etiquetas de la imagen.',
              senior: R`Pipeline automático (Apéndice B): frases nominales con n-gramas → GLIP-L propone cajas para esas frases → CLIP re-puntúa cada recorte (\(\tilde c = \sqrt{c\cdot s^r}\)) y opcionalmente lo re-etiqueta → NMS por frase (0.5) y umbral 0.3 → filtro por imagen con \(\sqrt{s^{img}\cdot s^{region}}\) &gt; 0.3. Salen 246k imágenes y 821k cajas de CC3M, y la pérdida de caja se apaga para ellas. Qué puede salir mal: el modelo hereda los errores de GLIP (es destilación de un detector más grande), sesgos de CLIP en el filtrado, y ruido que con modelos chicos puede bajar el AP: en el Apéndice C, el modelo S con más pseudo-etiquetas (520k → 750k) baja de 19.2 a 18.2, mientras que GoldG, anotado por humanos, da 24.2.`,
              say: 'Noun phrases are extracted from captions, GLIP proposes boxes for them, CLIP rescores and optionally relabels each crop, then per-phrase NMS and score thresholds filter regions and an image-level score filters images; box regression loss is disabled for this data. It is essentially distillation from a larger grounding model, so it inherits its errors, and the appendix shows that too much pseudo-labeled data can hurt small models.',
              why: 'Se anota: GLIP + CLIP, λ_I = 0 para esas cajas, y el resultado del Apéndice C (calidad > cantidad).' },
            { q: 'Your YOLO-World detects "helmet" well alone, but when you add 30 more classes the helmet recall drops. Why?',
              junior: 'Porque hay más clases que confundir.',
              senior: R`Tres mecanismos, de más a menos probable. (1) <b>El neck</b>: la max-sigmoid toma el máximo sobre todo el vocabulario, así que agregar palabras cambia las features de cada posición, y con ellas los logits de "helmet" (en la cabeza, en cambio, cada logit es independiente). (2) <b>Competencia en el post-proceso</b>: clases parecidas ("hard hat", "cap", "hat") se llevan la caja con mayor puntuación y, con top-k o un máximo de detecciones por imagen, desplazan a "helmet". (3) <b>Calibración distinta</b> entre vocabularios: el umbral que funcionaba con una clase no sirve con 31. También existe el efecto inverso, documentado en el repo: el entrenamiento rellenaba el vocabulario hasta 80 con cadenas vacías, y con pocas clases suele hacer falta agregar ese relleno. Diagnóstico: comparar logits de "helmet" con y sin las otras clases, agrupar sinónimos y re-calibrar umbrales por clase.`,
              say: 'The max-sigmoid gate in the neck takes a max over the whole vocabulary, so adding classes changes the features and therefore the helmet logits, and similar classes compete in post-processing and top-k. I would compare helmet logits with and without the extra classes, merge synonyms and recalibrate thresholds.',
              why: 'Trampa: "más clases que confundir". Se anota el máximo del neck y la competencia en el post-proceso.', trap: true },
            { q: 'Why does YOLO-World use the CLIP text encoder and not BERT, and why keep it frozen?',
              junior: 'Porque CLIP es más nuevo.',
              senior: R`Tabla 5: CLIP-base congelado da 22.4 AP zero-shot en LVIS, BERT-base congelado 14.6; en raras, 14.5 vs 3.4. CLIP aprendió embeddings de texto alineados con contenido visual (contrastivo con imágenes); BERT, con contexto lingüístico. Congelado porque fine-tunearlo sobre O365 (365 categorías) lo empeora: 19.3 AP, frente a 22.4 congelado. Con pocas categorías, el encoder se colapsa hacia ellas y pierde la generalidad que justamente se quería. A BERT sí le sirve fine-tunearse (14.6 → 18.3), porque parte de más lejos. En el fine-tuning posterior (COCO, LVIS) el paper sí lo ajusta, pero con LR × 0.01. Repregunta: "¿entonces Grounding DINO eligió mal con BERT?". No: son regímenes distintos. Aquí el encoder está congelado y aporta un vector por clase a una fusión liviana, así que necesita llegar ya alineado con imágenes. En <a href="#grounding-dino">Grounding DINO</a>, BERT se entrena con millones de pares frase-caja y fusión profunda token a token; además, de la torre causal de CLIP solo el token EOT está supervisado, así que sus features por token no tienen por qué servir allí. Ninguno de los dos papers ablaciona CLIP dentro de la arquitectura del otro: dilo así.`,
              say: 'CLIP\'s text embeddings are already aligned with visual content, which shows in the ablation: frozen CLIP beats frozen BERT by about eight AP on zero-shot LVIS. Fine-tuning CLIP on a 365-class detection set hurts, because it overfits the encoder to those categories and loses the generality the model relies on. That does not make Grounding DINO wrong: there BERT is fine-tuned with deep per-token fusion, a different regime.',
              why: 'Citar la Tabla 5 con los dos efectos (CLIP > BERT, congelar > fine-tunear) es la señal.' },
            { q: 'What did YOLO-World v2 remove, and why is that a deployment lesson?',
              junior: 'Lo hicieron más chico.',
              senior: R`Dos cambios (docs/updates.md del repo): (1) quitaron la image-pooling attention, el camino imagen → texto: mejoraba el zero-shot en LVIS pero hacía que el vocabulario dependiera de cada imagen, así que no se podía plegar en pesos y empeoraba la velocidad tras exportar a ONNX/TensorRT; (2) cambiaron la L2-norm de la cabeza por BatchNorm: la L2 necesita una reducción por posición, mientras que BN en inferencia es afín y se pliega en la conv 1×1. La lección: en un modelo para edge, cada operación que depende de la entrada en un lugar donde podría haber pesos fijos cuesta en el runtime aunque sus MACs sean despreciables. Se diseña para el grafo exportado, no para el paper.`,
              say: 'Version 2 dropped image-pooling attention, because an image-dependent vocabulary cannot be folded into weights and slowed down exported models, and replaced the L2 norm in the contrastive head with BatchNorm, which folds into the 1×1 conv. The lesson is to design for the exported graph: input-dependent ops cost real latency even when their FLOPs are negligible.',
              why: 'Se anota: el porqué de cada cambio y la lección de diseño para deploy.' },
            { q: 'YOLO-World vs YOLOE vs OWLv2: when would you pick each?',
              junior: 'El más nuevo siempre.',
              senior: R`<b>YOLO-World</b>: vocabulario de texto conocido por sesión y tiempo real; ecosistema maduro (Ultralytics, export). <b>YOLOE</b> (ICCV 2025): mismo nicho de tiempo real, pero sin fusión en el neck (refina los embeddings de texto con una red auxiliar que se re-parametriza: costo cero), con prompts visuales y un modo sin prompt, y segmenta; su paper reporta +3.5 AP en LVIS sobre YOLO-Worldv2-S con 3× menos costo de entrenamiento y 1.4× más velocidad. Si empiezo hoy y quiero prompts visuales o máscaras, lo evaluaría primero. <b>OWLv2</b>: calidad en clases raras (auto-entrenamiento a escala web; 44.6 AP<sub>r</sub> en LVIS con L/14 según su abstract) y detección con una imagen de ejemplo, pero un ViT grande a alta resolución: etiquetado offline, no un Jetson. Decido con mis datos: zero-shot en un set de validación de mi dominio y latencia medida en el dispositivo.`,
              say: 'YOLO-World for real-time detection with a text vocabulary and a mature export path; YOLOE for the same budget when I also need visual prompts, prompt-free detection or masks, since it avoids neck fusion entirely and reports better LVIS accuracy than YOLO-World v2; OWLv2 when rare-class quality matters more than latency, for example offline labeling.',
              why: 'Se anota que conozcas el estado actual (YOLOE) y que decidas por datos y latencia medidos.' },
            { q: 'Your vocabulary has 1,203 LVIS classes. What changes in cost and behavior compared with 80?',
              junior: 'Es 15 veces más lento.',
              senior: R`En MACs, poco: la parte que depende de V es la conv 1×1 de la cabeza (${cE()} → V por nivel) y las similitudes de los T-CSPLayers; ambas son lineales en V, y el backbone y la rama de caja no cambian (el explorador de la <a href="#yolo-world.costo">sección 5</a> lo muestra). Lo que sí crece: el tensor de logits (${qn('quantities.anchors')} × V), el post-proceso (más pares caja-clase sobre el umbral, NMS multi-etiqueta más pesado) y la confusión entre clases parecidas (LVIS tiene muchas casi sinónimas). Y el neck cambia de comportamiento: el máximo de la max-sigmoid sobre 1,203 palabras enciende casi todo. Por eso LVIS se evalúa con <b>Fixed AP</b>: sin tope por imagen y hasta 10,000 detecciones por clase en el dataset, para que las clases raras no queden fuera; el modelo, además, da hasta 1000 predicciones por imagen (§4.2).`,
              say: 'FLOPs barely change, since only the head\'s 1×1 conv and the neck similarities are linear in the vocabulary. What grows is the logits tensor, post-processing and NMS work, and confusion between near-synonyms; the max-sigmoid gate also lights up almost everywhere with a huge vocabulary.',
              why: 'Trampa: suponer costo ∝ V en todo el modelo. Se anota qué parte es lineal en V y dónde aparece el costo real.', trap: true },
            { q: 'On correct detections YOLO-World scores about 0.3 for "forklift" and 0.6 for "person". How do you set thresholds?',
              junior: 'Uso 0.25 para todo, como en YOLO.',
              senior: R`Las sigmoides de un detector abierto no son probabilidades comparables entre clases: dependen de cuánto se parece el embedding de esa palabra a lo que el modelo vio en el preentrenamiento, de la redacción del prompt, del β compartido y, en YOLO-World, del resto del vocabulario (la max-sigmoid del neck toma el máximo sobre todas las palabras). Un umbral global favorece a las clases "fáciles" y castiga a las raras. Proceso: (1) un set de validación de mi dominio con todas las clases, etiquetado a mano; (2) por clase, la curva precision-recall y un punto de operación elegido por el costo del error (en un robot, perder una persona cuesta más que una falsa alarma: umbral bajo para "person"); (3) si necesito probabilidades para fusionar con un tracker u otros sensores, calibración por clase (Platt o temperatura por clase) y medir el ECE; (4) recalibrar cada vez que cambia el vocabulario o la redacción, porque las puntuaciones cambian con él; (5) en producción, vigilar la distribución de puntuaciones por clase para detectar drift.`,
              say: 'Open-vocabulary scores are not comparable across classes: they depend on the word, the phrasing and, in YOLO-World, on the rest of the vocabulary. I pick a per-class operating point from precision-recall curves on in-domain validation data, weighted by the cost of each error, calibrate per class if downstream fusion needs probabilities, and recalibrate whenever the vocabulary changes.',
              why: 'Trampa: un umbral global. Se anota: por clase, por costo del error, y recalibrar al cambiar el vocabulario.', trap: true },
            { q: 'How do you write the vocabulary? Synonyms, plurals, negatives?',
              junior: 'Pongo los nombres de mis clases.',
              senior: R`Reglas que se miden, no se adivinan. (1) Nombres concretos, como aparecerían en O365 o en un caption: "forklift" mejor que "industrial vehicle"; para palabras ambiguas, una frase que desambigua ("baseball bat"). (2) Sinónimos, dos opciones: promediar los embeddings normalizados de varias frases en una sola fila (prompt ensembling, como en CLIP), o poner varias filas que mapean a la misma clase y quedarme con la máxima. La segunda es más robusta, pero agrega competencia en el neck y duplicados que una NMS por clase no fusiona: hay que unirlos después. (3) Singular por defecto: las clases de entrenamiento están en singular, y el plural puede cambiar las puntuaciones; pruébalo. (4) Negativos: "not a helmet" no funciona, porque no hay negación, solo similitud. Lo que sí funciona es agregar clases distractoras ("cap", "hat") que absorban los falsos positivos, y descartarlas en el post-proceso. (5) Con pocas clases, mantener el relleno hasta 80 que el modelo vio en entrenamiento (nota de la v2.1 del repo). Cada cambio de prompt se valida en un set propio y obliga a recalibrar los umbrales.`,
              say: 'Concrete names in the style of the pre-training data, disambiguated phrases for ambiguous words, synonyms either averaged into one embedding or as separate rows merged after detection, singular forms by default, and no negations: instead I add distractor classes that absorb false positives and drop them in post-processing. Every change is validated on my own set and the thresholds are recalibrated.',
              why: 'Se anota: ensembling vs filas múltiples, distractores en vez de negación, y validar cada cambio.' },
            { q: 'Your re-parameterized YOLO-World-L hits 52 FPS on a V100. What dominates latency on a Jetson Orin, and how do you find out?',
              junior: 'Lo mismo que en la V100, pero más lento.',
              senior: R`El reparto cambia. (1) <b>La red</b>: el backbone sigue siendo la mayor parte de los MACs (${npc('backbone')}), pero en el Orin el ancho de banda de memoria es mucho menor que en una GPU de servidor, así que las activaciones grandes de P3 pesan más de lo que dicen sus MACs. Se baja con FP16 o INT8 en TensorRT (todo son convs tras re-parametrizar) y, si hace falta, repartiendo capas entre la GPU y los DLA. (2) <b>El post-proceso</b>: decodificar ${qn('quantities.anchors')} × V puntuaciones, el top-k y NMS. En la V100 son despreciables; en el Orin, si corren en Python sobre la CPU ARM, pueden costar tanto como la red. Mejor dentro del motor (plugin EfficientNMS) o en GPU. Crecen con V y con el número de cajas sobre el umbral. (3) <b>El preprocesado</b>: letterbox, normalización y la copia a la GPU; en la CPU ARM se nota, y conviene moverlo a la GPU. (4) <b>El vocabulario en caliente</b>: si cambias las clases en el robot sin un servidor, el text encoder de CLIP corre en el Orin. Es una vez por cambio, no por frame, pero no puede caer en el lazo de control. Cómo lo mido: trtexec para el motor solo, Nsight Systems para el pipeline completo, batch 1, latencia p99 (no la media), con el modo de energía y los relojes que usará el robot ${est('(el reparto exacto depende del modelo de Orin, del modo de energía y de tu vocabulario)')}.`,
              say: 'On an Orin the network is still mostly backbone, but memory bandwidth is much lower, so large high-resolution activations cost more than their FLOPs suggest; FP16 or INT8 TensorRT helps because the re-parameterized model is all convolutions. Then post-processing: decoding anchors times vocabulary scores, top-k and NMS can cost as much as the network if they run in Python on the ARM CPU, so I move them into the engine. I profile with trtexec and Nsight Systems at batch one and track p99 latency under the robot\'s real power mode.',
              why: 'Se anota: red vs post-proceso vs preprocesado medidos por separado, NMS en el motor, y p99 en el modo de energía real.', trap: true },
            { q: 'Your warehouse robot must stop for any obstacle, including things nobody put in the vocabulary. Is YOLO-World enough?',
              junior: 'Sí: es de vocabulario abierto, detecta cualquier cosa.',
              senior: R`No. Vocabulario abierto quiere decir que <b>tú</b> eliges las clases en inferencia, no que detecte todo: lo que no está en la lista no tiene fila con qué compararse, y no sale (o sale con el nombre más parecido, con poca confianza). "Cualquier obstáculo" es otra pregunta: <b>open-world</b>, detectar lo desconocido como "unknown". Opciones: (1) un detector o segmentador class-agnostic (propuestas de objeto, SAM en modo "todo"); (2) un modelo open-world con clase comodín, como YOLO-UniOW (<a href="#yolo-world.variantes">variantes</a>), o el modo sin prompt de YOLOE, que usa un vocabulario interno grande; (3) palabras genéricas como "object" u "obstacle" en el vocabulario ayudan poco y hay que medirlas, porque CLIP las asocia a pocos ejemplos visuales; (4) sobre todo, una capa geométrica que no depende de la semántica: profundidad, nube de puntos, mapa de ocupación. En un robot, la seguridad la da la geometría; el detector abierto agrega semántica encima ("es una persona: frena antes y deja más margen").`,
              say: 'No. Open vocabulary means I choose the classes at inference; anything not in the list has nothing to match and will not be detected. For unknown obstacles I need class-agnostic objectness or an open-world detector with an unknown class, and for safety a geometric layer from depth or point clouds; the open-vocabulary detector adds semantics on top.',
              why: 'Trampa: confundir vocabulario abierto con open-world. Se anota que la seguridad no depende de un prompt.', trap: true },
            { q: 'You need 12 fixed classes at 30 FPS on a Jetson. Deploy YOLO-World as is, fine-tune it, or distill into a closed YOLOv8?',
              junior: 'YOLO-World, porque ya conoce las clases.',
              senior: R`Depende de lo que mida en un <b>set de auditoría</b> etiquetado a mano (unos cientos a mil imágenes de mi dominio, estratificado por cámara y escena); es lo primero que armo, porque es el único juez honesto. (1) <b>Tal cual</b>, re-parametrizado con mis 12 palabras: listo en una tarde y con costo de un YOLO; si el zero-shot ya alcanza en mis clases, termino aquí. (2) <b>Fine-tuning de YOLO-World</b> con mis etiquetas (o sobre la versión re-parametrizada): si no necesito el vocabulario abierto, es un YOLOv8 bien inicializado. (3) <b>Destilar a un YOLOv8 cerrado</b>: es lo que hizo el propio YOLO-World con GLIP sobre CC3M. Un maestro offline sin presupuesto de latencia (Grounding DINO o YOLO-World a 1280, con prompts por clase y TTA) pseudo-etiqueta las imágenes sin etiquetar. Umbral por clase, elegido en el set de auditoría para precisión alta. Y lo que más se olvida: los falsos negativos del maestro se vuelven "fondo" para el alumno y le enseñan a no detectar; las cajas de confianza media van como regiones <i>ignore</i> o a revisión humana. Gano un poco de latencia frente a YOLO-World (YOLO-World-L cuesta ${qn('metrics.macsVsYolov8')} veces un YOLOv8-L), pierdo el vocabulario abierto, y el alumno suele igualar al maestro en mis clases porque aprende mi dominio. En el robot: guardar los frames dudosos, re-etiquetarlos y reentrenar (data engine).`,
              say: 'I first hand-label an audit set. If re-parameterized YOLO-World with my twelve words is good enough on it, I ship that. Otherwise I fine-tune it, or distill: an offline teacher pseudo-labels unlabeled images with per-class thresholds tuned for precision, mid-confidence boxes become ignore regions because the teacher\'s misses would teach background, and a closed YOLOv8 is trained and compared with the teacher on the audit set. YOLO-World itself was built that way, with GLIP labels on caption data.',
              why: 'Se anota: el set de auditoría primero, las tres opciones por costo, umbrales por clase y el problema de los falsos negativos del maestro.', trap: true },
          ] },
          { t: 'qa', items: [
            { q: '¿Qué forma tienen los logits de P3 de YOLO-World-L a 640 con V = 80, y de dónde salen?', a: R`${sh('logits-p3')} (${sy('logits-p3')}): ${sh('obj-emb-p3')} object embeddings normalizados por el vocabulario normalizado ${sh('vocab')} transpuesto, × α + β.` },
            { q: '¿Cuántos tokens ve la image-pooling attention y por qué no depende de la resolución?', a: 'Max pooling adaptativo a 3×3 en cada uno de los 3 niveles: 27 tokens (§3.3). El pooling es adaptativo: siempre da 3×3, sea cual sea el tamaño del mapa.' },
            { q: '¿Qué diferencia hay entre el 48M y el 110M de la Tabla 2 para YOLO-World-L?', a: R`48M es la versión re-parametrizada (el detector, sin text encoder); 110M incluye el text encoder de CLIP (en el calculador, ${tP} parámetros). Lo mismo con 52.0 vs 17.6 FPS.` },
            { q: '¿Qué parte del modelo se fine-tunea con LR × 0.01 y en qué etapa?', a: 'El text encoder de CLIP, solo en el fine-tuning posterior (COCO, LVIS; §4.4). En el preentrenamiento está congelado (§4.2).' },
          ] },
          { t: 'callout', kind: 'interview', title: 'Dilo así (en inglés)', html: R`<p><b>One-liner:</b> "YOLO-World is YOLOv8 with a region-text contrastive head and a text-guided PAN, pre-trained on detection, grounding and pseudo-labeled caption data with a frozen CLIP text encoder."</p><p><b>Why it is fast:</b> "Prompt-then-detect: the vocabulary is encoded once and re-parameterized into 1×1 conv weights, so inference is a plain YOLO."</p><p><b>What it is not:</b> "It is still a dense one-to-many detector with NMS, and its fusion is shallow, so long referring expressions are Grounding DINO territory."</p><p><b>Today:</b> "YOLO-World v2 for deployment, YOLOE when you need visual prompts or masks, Grounding DINO for referring phrases and OWLv2 for rare classes offline, after comparing on my own data."</p>` },
        ],
      },

      // ======================================================== 11
      {
        id: 'practica',
        titleEn: 'Active practice',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`Primero el diagrama sin mirar la página; después, las formas con números; al final, los "¿qué pasa si…?" y los ejercicios de código de la cabeza contrastiva y de la max-sigmoid. Todas las respuestas numéricas las calcula el calculador.` },
          { t: 'h3', text: 'Diagrama en blanco: YOLO-World completo' },
          { t: 'blankdiagram', diagram: 'yolo-world-overview', slots: [
            { node: 'txt-encoder', ask: 'label' },
            { node: 'vocab', tensor: 'vocab', ask: 'shape' },
            { node: 'neck', ask: 'label' },
            { node: 'head-text', tensor: 'logits-p3', ask: 'shape' },
            { node: 'head-box', ask: 'label' },
          ] },
          { t: 'h3', text: '¿Qué forma tiene este tensor?' },
          { t: 'shapedrill', model: 'yolo-world', pool: 'all', configs: [C] },
          { t: 'h3', text: '¿Qué pasa si…?' },
          { t: 'whatif', items: [
            { q: R`Subes el vocabulario de ${cV()} a 1203 palabras (LVIS). ¿Por qué factor cambian los MACs del detector?`, change: { V: 1203 }, ask: 'macs',
              explain: 'Poco: solo la conv 1×1 de la cabeza (E → V por nivel) y las similitudes de los T-CSPLayers son lineales en V; backbone, convs del PAN y rama de caja no cambian.' },
            { q: 'Mismas 1203 palabras. ¿Por qué factor cambian los parámetros del detector?', change: { V: 1203 }, ask: 'params',
              explain: 'Nada: en el modelo (y en el calculador) el vocabulario es una entrada, no un parámetro; por eso puedes cambiarlo sin reentrenar. Solo al re-parametrizar cada palabra se vuelve pesos: E por nivel en la cabeza y, en cada max-sigmoid del neck, tantos como su ancho de embedding (menor que E).' },
            { q: 'YOLO-World-L a 1280×1280 en vez de 640×640. ¿Por qué factor cambia el número de puntos de anclaje?', change: { res: 1280 }, ask: 'tokens',
              explain: '(1280/640)² = 4: puntos de anclaje ∝ área en los tres niveles.' },
            { q: 'Misma subida a 1280. ¿Por qué factor cambian los MACs?', change: { res: 1280 }, ask: 'macs',
              explain: 'Todo es convolucional y lineal en posiciones (la image-pooling attention siempre ve 27 tokens): ≈ ×4, sin término cuadrático.' },
            { q: 'Bajas a 320×320 para un microcontrolador. ¿Por qué factor cambian los MACs?', change: { res: 320 }, ask: 'macs',
              explain: '÷4 aproximadamente: el área. A cambio, P3 a 320 tiene 40×40 celdas y los objetos chicos desaparecen.' },
          ] },
          { t: 'h3', text: 'Escríbelo: la cabeza región-texto y su re-parametrización' },
          { t: 'p', html: R`El ejercicio de código que se pide cuando sale YOLO-World. Sin mirar: dados los object embeddings de un nivel (<code>obj: (B, E, H, W)</code>), el vocabulario (<code>txt: (V, E)</code>) y los escalares aprendidos <code>log_alpha</code> y <code>beta</code>, calcula los logits <code>(B, V, H, W)</code> con la ecuación 1. Después conviértela en una <code>Conv2d</code> 1×1 con el vocabulario plegado en los pesos, y (extra) haz lo mismo con la versión v2, donde la imagen pasa por BatchNorm en vez de L2-norm. La solución está verificada en el venv del Atlas (PyTorch 2.14, float64): la versión con conv da los mismos logits que la directa (diferencia máxima 5.9·10⁻¹⁴ con L2 en P3, P4 y P5 a 640; 3.1·10⁻¹³ con BN plegada; del orden de 10⁻⁵ en float32, según la semilla), y agregar una palabra deja idénticos los 80 logits anteriores.` },
          { t: 'code', title: 'Solución de referencia (PyTorch)', files: [
            { name: 'region_text_head.py', lang: 'python', code: [
              'import torch',
              'import torch.nn.functional as F',
              '',
              '',
              'def region_text_logits(obj, txt, log_alpha, beta):',
              '    # obj: (B, E, H, W) object embeddings de un nivel; txt: (V, E) embeddings de texto (CLIP)',
              '    # log_alpha, beta: escalares aprendidos (alpha = exp(log_alpha), como el logit_scale de CLIP)',
              '    obj = F.normalize(obj, dim=1)                        # (B, E, H, W): norma 1 por posición',
              '    txt = F.normalize(txt, dim=-1)                       # (V, E): norma 1 por clase',
              "    s = torch.einsum('bdhw,vd->bvhw', obj, txt)          # (B, V, H, W): cosenos en [-1, 1]",
              '    return log_alpha.exp() * s + beta                    # logits (sigmoide por clase en la pérdida)',
              '',
              '',
              'def reparam_to_conv(txt, log_alpha, beta):',
              '    # El vocabulario ya está fijo: lo convertimos en una conv 1×1 de E → V canales.',
              '    V, E = txt.shape',
              '    conv = torch.nn.Conv2d(E, V, kernel_size=1, bias=True, dtype=txt.dtype)',
              '    with torch.no_grad():',
              '        conv.weight.copy_((log_alpha.exp() * F.normalize(txt, dim=-1)).view(V, E, 1, 1))',
              '        conv.bias.fill_(beta.item())                     # el mismo beta para las V clases',
              '    return conv',
              '',
              '',
              'def rep_head_l2(obj, conv):',
              '    # La L2-norm de la imagen depende de cada píxel: no se puede meter en los pesos.',
              '    return conv(F.normalize(obj, dim=1))                 # (B, V, H, W)',
              '',
              '',
              'def reparam_bn_to_conv(bn, txt, log_alpha, beta):',
              '    # Variante v2 (BNContrastiveHead): BN en lugar de L2 sobre la imagen. En eval, BN es afín por',
              "    # canal, x' = a·x + b, así que se pliega en la conv: W' = alpha·Ŵ·diag(a), b' = beta + alpha·Ŵ·b.",
              '    a = bn.weight / torch.sqrt(bn.running_var + bn.eps)  # (E,)',
              '    b = bn.bias - a * bn.running_mean                    # (E,)',
              '    Wn = log_alpha.exp() * F.normalize(txt, dim=-1)      # (V, E)',
              '    V, E = txt.shape',
              '    conv = torch.nn.Conv2d(E, V, kernel_size=1, bias=True, dtype=txt.dtype)',
              '    with torch.no_grad():',
              '        conv.weight.copy_((Wn * a).view(V, E, 1, 1))',
              '        conv.bias.copy_(beta + Wn @ b)',
              '    return conv                                          # una sola conv 1×1, sin normalización',
              '',
              '',
              'def bn_head(obj, bn, txt, log_alpha, beta):',
              '    x = bn(obj)                                          # (B, E, H, W)',
              "    s = torch.einsum('bdhw,vd->bvhw', x, F.normalize(txt, dim=-1))",
              '    return log_alpha.exp() * s + beta',
            ].join('\n') },
            { name: 'check_reparam.py', lang: 'python', code: [
              'import math',
              'import torch',
              'from region_text_head import region_text_logits, reparam_to_conv, rep_head_l2, reparam_bn_to_conv, bn_head',
              '',
              'torch.manual_seed(0)',
              'B, E, V = 2, 512, 80',
              'log_alpha = torch.tensor(math.log(1 / 0.07), dtype=torch.float64)   # init de CLIP: alpha ≈ 14.3',
              'beta = torch.tensor(-10.0, dtype=torch.float64)                     # init de Ultralytics',
              'txt = torch.randn(V, E, dtype=torch.float64)',
              '',
              'for H, W in [(80, 80), (40, 40), (20, 20)]:                         # P3, P4, P5 a 640×640',
              '    obj = torch.randn(B, E, H, W, dtype=torch.float64)',
              '    ref = region_text_logits(obj, txt, log_alpha, beta)              # (B, V, H, W)',
              '    rep = rep_head_l2(obj, reparam_to_conv(txt, log_alpha, beta))',
              '    assert rep.shape == ref.shape == (B, V, H, W)',
              '    assert (rep - ref).abs().max() < 1e-12',
              '',
              '# Agregar una clase: una fila nueva de texto = un canal de salida nuevo; los demás no cambian.',
              'txt2 = torch.cat([txt, torch.randn(1, E, dtype=torch.float64)])',
              'obj = torch.randn(B, E, 20, 20, dtype=torch.float64)',
              'assert torch.equal(region_text_logits(obj, txt, log_alpha, beta),',
              '                   region_text_logits(obj, txt2, log_alpha, beta)[:, :V])',
              '',
              '# Variante con BN (YOLO-World v2): todo se pliega en una sola conv.',
              'bn = torch.nn.BatchNorm2d(E, dtype=torch.float64)',
              'with torch.no_grad():',
              '    bn.weight.uniform_(0.5, 1.5); bn.bias.normal_()',
              '    bn.running_mean.normal_(); bn.running_var.uniform_(0.5, 2.0)',
              'bn.eval()',
              'obj = torch.randn(B, E, 40, 40, dtype=torch.float64)',
              'ref = bn_head(obj, bn, txt, log_alpha, beta)',
              'rep = reparam_bn_to_conv(bn, txt, log_alpha, beta)(obj)',
              'assert (rep - ref).abs().max() < 1e-10',
              'print("ok")',
            ].join('\n'), note: 'Las tolerancias son de float64; en float32 la diferencia es de redondeo (≈ 10⁻⁵ con logits de magnitud ≈ 10).' },
          ] },
          { t: 'p', html: R`<b>Los bugs que el entrevistador busca</b> (casi todos corren sin error):` },
          { t: 'list', items: [
            R`Normalizar el object embedding en el eje equivocado (<code>dim=0</code>, el batch, en vez de <code>dim=1</code>, los canales): corre y da cosenos falsos (en el test, diferencias de hasta ≈ 3).`,
            R`Plegar también la L2-norm de la imagen en los pesos: no se puede, depende de cada posición. Solo el lado del texto (y α, β) se pliega; con BN (v2) sí se pliega todo, porque en eval BN es afín.`,
            R`Olvidar α: los logits quedan en [−1 + β, 1 + β] y la sigmoide no separa clases. O usar α directamente como parámetro sin la exponencial: puede volverse negativo y dar vuelta el ranking.`,
            R`Crear la <code>Conv2d</code> en float32 y copiarle pesos en float64: la conversión silenciosa da diferencias de ≈ 10⁻⁷ que parecen un bug de la re-parametrización (nos pasó al verificar).`,
            R`Plegar BN sin <code>bn.eval()</code>: en modo train usa las estadísticas del batch y la versión plegada no coincide.`,
            R`Softmax sobre el vocabulario en vez de sigmoide por clase: cambia la semántica (las clases compiten) y no es lo que entrena el código.`,
          ] },
          { t: 'h3', text: 'Escríbelo (corto): la max-sigmoid re-parametrizada' },
          { t: 'p', html: R`La otra mitad de "what exactly becomes weights": la max-sigmoid del T-CSPLayer, con cabezas como en <code>MaxSigmoidAttnBlock</code>. El texto ya pasó por <code>guide_fc</code> (<code>guide: (V, nh·hc)</code>), las features por su conv 1×1 (<code>embed: (B, nh·hc, H, W)</code>) y hay un sesgo por cabeza (<code>bias: (nh,)</code>). Escribe el gate directo (similitud por cabeza con las V palabras, máximo sobre V, ÷√hc, + sesgo, sigmoide → <code>(B, nh, H, W)</code>) y después la versión con el vocabulario fijo: una conv 1×1 <b>agrupada</b> (nh grupos, cada uno hc → V canales) seguida de un máximo sobre los V canales de cada grupo. El gate multiplica la salida de <code>project_conv</code> (3×3 + BN), que no depende del texto y no cambia. Verificado en el venv del Atlas (PyTorch 2.14, float64): diferencia máxima 3.3·10⁻¹⁶ en mapas de 80×80, 40×40 y 20×20.` },
          { t: 'code', title: 'Solución de referencia (PyTorch)', files: [
            { name: 'max_sigmoid.py', lang: 'python', code: [
              'import math',
              'import torch',
              '',
              '',
              'def max_sigmoid_gate(embed, guide, bias, nh):',
              '    # embed: (B, nh*hc, H, W) features de imagen · guide: (V, nh*hc) texto tras guide_fc · bias: (nh,)',
              '    B, C, H, W = embed.shape',
              '    hc, V = C // nh, guide.shape[0]',
              "    s = torch.einsum('bmchw,nmc->bmhwn', embed.view(B, nh, hc, H, W), guide.view(V, nh, hc))  # (B, nh, H, W, V)",
              '    s = s.amax(-1) / math.sqrt(hc) + bias[None, :, None, None]   # (B, nh, H, W): máximo sobre V',
              '    return s.sigmoid()                                            # un gate por cabeza y posición',
              '',
              '',
              'def reparam_gate(guide, nh):',
              '    # Vocabulario fijo → conv 1×1 AGRUPADA: nh grupos, cada uno hc → V canales.',
              '    V, C = guide.shape',
              '    hc = C // nh',
              '    conv = torch.nn.Conv2d(C, nh * V, kernel_size=1, groups=nh, bias=False, dtype=guide.dtype)',
              '    with torch.no_grad():   # salida (m, n) del grupo m ← guide[n, m, :] / √hc',
              '        conv.weight.copy_(guide.view(V, nh, hc).permute(1, 0, 2).reshape(nh * V, hc, 1, 1) / math.sqrt(hc))',
              '    return conv',
              '',
              '',
              'def rep_gate(embed, conv, bias, nh):',
              '    B, _, H, W = embed.shape',
              '    s = conv(embed).view(B, nh, -1, H, W).amax(2)                 # máximo sobre los V canales de cada grupo',
              '    return (s + bias[None, :, None, None]).sigmoid()',
            ].join('\n') },
            { name: 'check_max_sigmoid.py', lang: 'python', code: [
              'import torch',
              'from max_sigmoid import max_sigmoid_gate, reparam_gate, rep_gate',
              '',
              'torch.manual_seed(0)',
              'B, nh, hc, V = 2, 4, 32, 80                     # 4 cabezas de 32 canales, 80 palabras',
              'guide = torch.randn(V, nh * hc, dtype=torch.float64)',
              'bias = torch.randn(nh, dtype=torch.float64)',
              'conv = reparam_gate(guide, nh)',
              'assert conv.weight.shape == (nh * V, hc, 1, 1)',
              'worst = 0.0',
              'for H, W in [(80, 80), (40, 40), (20, 20)]:',
              '    embed = torch.randn(B, nh * hc, H, W, dtype=torch.float64)',
              '    ref = max_sigmoid_gate(embed, guide, bias, nh)              # (B, nh, H, W)',
              '    rep = rep_gate(embed, conv, bias, nh)',
              '    assert rep.shape == ref.shape == (B, nh, H, W)',
              '    worst = max(worst, (rep - ref).abs().max().item())',
              'assert worst < 1e-12',
              '',
              '# Bug típico: olvidar groups=nh. Con una conv densa de C → nh·V las cabezas se mezclan (y la forma ni siquiera coincide).',
              'dense = torch.nn.Conv2d(nh * hc, nh * V, 1, bias=False, dtype=torch.float64)',
              'assert dense.weight.shape != conv.weight.shape',
              '# Bug típico: reshape (V, nh) en vez de (nh, V). Corre y da otra función.',
              'bad = torch.nn.Conv2d(nh * hc, nh * V, 1, groups=nh, bias=False, dtype=torch.float64)',
              'with torch.no_grad():',
              '    bad.weight.copy_(guide.view(nh * V, hc, 1, 1) / hc ** 0.5)',
              'embed = torch.randn(B, nh * hc, 40, 40, dtype=torch.float64)',
              'assert (rep_gate(embed, bad, bias, nh) - max_sigmoid_gate(embed, guide, bias, nh)).abs().max() > 1e-3',
              'print("ok", worst)',
            ].join('\n'), note: 'Dividir por √hc dentro de los pesos es exacto porque √hc > 0: el máximo de valores escalados es el máximo escalado. El repo oficial trae dos formas re-parametrizadas: RepMatrixMaxSigmoidAttnBlock (un matmul contra el texto guardado) y RepConvMaxSigmoidAttnBlock (una conv 1×1 por cabeza sobre su grupo de canales, que es exactamente esta conv agrupada; divide por √hc después del máximo).' },
          ] },
          { t: 'p', html: R`<b>Los bugs que busca el entrevistador:</b> olvidar <code>groups=nh</code> (la conv mezcla las cabezas); el orden del reshape, (V, nh) en vez de (nh, V), que corre sin error y calcula otra función; tomar el máximo sobre los nh·V canales juntos en vez de dentro de cada grupo; y querer plegar también <code>project_conv</code>, que no depende del texto.` },
          { t: 'h3', text: 'Estima y depura' },
          { t: 'qa', items: [
            { q: 'Exportas YOLO-World v1 a ONNX con opset 11 y falla con "Exporting the operator einsum … is not supported". ¿Qué haces?', a: 'einsum entra en ONNX desde el opset 12: sube a opset 12, o pon use_einsum=False en la config (en MaxSigmoidCSPLayerWithTwoConv y en YOLOWorldHeadModule; docs/deploy.md trae una config de ejemplo) para que se exporte como permute/reshape/matmul. Mejor aún: re-parametriza (v2) y exporta convs.' },
            { q: 'Con el vocabulario ["person"], YOLO-World da cajas raras con puntuaciones bajas; con ["person", " "] mejora. ¿Por qué?', a: 'El entrenamiento rellenaba el vocabulario hasta 80 y no enmascaraba el relleno en el neck (la config rellena con cadenas vacías, <code>padding_value=\'\'</code>; los demos del repo agregan " "): el relleno actúa como un "embedding de fondo" que el modelo aprendió a esperar (nota de la v2.1 del repo). Con un vocabulario de una palabra, la max-sigmoid del neck queda fuera de su distribución de entrenamiento.' },
            { q: 'Tu detector re-parametrizado con 10 clases va a 8 ms en el Jetson; con 400 clases, a 14 ms. Los MACs casi no cambiaron. ¿Dónde buscas?', a: R`En el post-proceso: más pares (caja, clase) sobre el umbral entran a NMS multi-etiqueta (y su costo depende de los datos), y la decodificación de ${qn('quantities.anchors')} × V puntuaciones pesa más. Perfila con Nsight o trtexec separando red y NMS; sube el umbral, limita top-k antes de NMS o reduce el vocabulario ${est('(los ms son un ejemplo ilustrativo: mídelos en tu equipo)')}.` },
          ] },
          { t: 'callout', kind: 'connect', html: R`<p>Repasa con las <a href="#flashcards">flashcards</a> de esta página y sigue con más ejercicios en <a href="#practica">Práctica</a>. La cabeza de clase es el clasificador zero-shot de <a href="#clip">CLIP</a> por posición; el contraste de fusión profunda (caro por imagen) es <a href="#grounding-dino">Grounding DINO</a>, y el porqué de NMS está en <a href="#detr">DETR</a>.</p>` },
        ],
      },
    ],

    // ---------------------------------------------------------- flashcards
    flashcards: [
      { id: 'yolo-world-01', kind: 'forma', q: 'YOLO-World-L a 640: formas de C3, C4 y C5.', a: R`${sh('c3')}, ${sh('c4')}, ${sh('c5')} (strides 8, 16, 32), igual que YOLOv8-L.` },
      { id: 'yolo-world-02', kind: 'forma', q: 'Forma del vocabulario codificado (V = 80).', a: R`${sy('vocab')} = ${sh('vocab')}: una fila de CLIP por palabra.` },
      { id: 'yolo-world-03', kind: 'forma', q: 'Forma de los object embeddings y de los logits en P3 (640, V = 80).', a: R`Embeddings ${sh('obj-emb-p3')}; logits ${sh('logits-p3')} (${sy('logits-p3')}).` },
      { id: 'yolo-world-04', kind: 'forma', q: 'Forma de los logits de P4 y P5 (640, V = 80).', a: R`${sh('logits-p4')} y ${sh('logits-p5')}.` },
      { id: 'yolo-world-05', kind: 'forma', q: 'Salida de la rama de caja en P3 (DFL).', a: R`${sh('boxes-p3')}: 4 lados × R = ${cR()} bins por punto.` },
      { id: 'yolo-world-06', kind: 'forma', q: '¿Cuántos tokens de imagen ve la image-pooling attention?', a: '27: max pooling adaptativo a 3×3 en cada uno de los 3 niveles (§3.3), sin importar la resolución.' },
      { id: 'yolo-world-07', kind: 'forma', q: 'Puntos de anclaje de YOLO-World / YOLOv8 a 640×640.', a: R`${qn('quantities.anchors')} = ${qn('quantities.p3Side')}² + ${qn('quantities.p4Side')}² + ${qn('quantities.p5Side')}² (strides 8, 16, 32).` },
      { id: 'yolo-world-08', kind: 'formula', q: 'Logit región-texto de YOLO-World (ec. 1).', a: R`\(s_{k,j} = \alpha\cdot\mathrm{L2}(\mathbf e_k)\cdot\mathrm{L2}(\mathbf w_j)^\top + \beta\), con α y β aprendidos.` },
      { id: 'yolo-world-09', kind: 'formula', q: 'Max-sigmoid attention del T-CSPLayer (ec. 2).', a: R`\(\mathbf X_l' = \mathbf X_l\cdot\delta\big(\max_j(\mathbf X_l\mathbf W_j^\top)\big)^\top\): un gate por posición con la similitud máxima al vocabulario.` },
      { id: 'yolo-world-10', kind: 'formula', q: 'Image-pooling attention (ec. 3).', a: R`\(\mathbf W' = \mathbf W + \mathrm{MHA}(\mathbf W,\tilde{\mathbf X},\tilde{\mathbf X})\), con \(\tilde{\mathbf X}\) = 27 tokens de max pooling 3×3 de P3, P4 (top-down) y C5; solo guía al camino bottom-up.` },
      { id: 'yolo-world-11', kind: 'formula', q: 'Pérdida total de YOLO-World.', a: R`\(\mathcal L = \mathcal L_\text{con} + \lambda_I(\mathcal L_\text{iou} + \mathcal L_\text{dfl})\), con λ_I = 0 para datos imagen-texto (cajas ruidosas).` },
      { id: 'yolo-world-12', kind: 'formula', q: 'Re-parametrización de la cabeza contrastiva (con L2).', a: R`Conv 1×1 con pesos \(\alpha\,\hat{\mathbf w}_j\) (V × E × 1 × 1) y sesgo β, aplicada al embedding normalizado. La L2 de la imagen no se pliega; con BN (v2) sí.` },
      { id: 'yolo-world-13', kind: 'conteo', q: 'Parámetros del detector de YOLO-World-L (calculador) y lo que reporta el paper.', a: R`${qn('params.total')} en el calculador; el paper: 48M re-parametrizado y 110M con el text encoder de CLIP (Tabla 2).` },
      { id: 'yolo-world-14', kind: 'conteo', q: 'MACs de YOLO-World-L a 640 frente a YOLOv8-L.', a: R`${qn('macs.totalG')} frente a ${qn('macs.totalG', Y8)} MACs (${qn('metrics.macsVsYolov8')} veces): la diferencia está casi toda en el neck (T-CSPLayers e image-pooling attention); la cabeza cambia poco.` },
      { id: 'yolo-world-15', kind: 'conteo', q: 'Parámetros del text encoder de CLIP que YOLO-World saca del camino online.', a: R`${tP}: corre una vez por vocabulario, no por imagen.` },
      { id: 'yolo-world-16', kind: 'conteo', q: 'Datos de preentrenamiento de YOLO-World (Tabla 1).', a: 'Objects365 V1 (609k imágenes), GQA (621k), Flickr30k (149k) y CC3M pseudo-etiquetado (246k imágenes, 821k cajas).' },
      { id: 'yolo-world-17', kind: 'conteo', q: 'Receta de preentrenamiento.', a: 'AdamW, LR 2·10⁻³, 100 épocas, batch 512; CLIP congelado (§4.2).' },
      { id: 'yolo-world-18', kind: 'conteo', q: 'YOLO-World-L zero-shot en LVIS minival (Tabla 2).', a: '35.4 Fixed AP (27.6 AP_r) con O365 + GoldG + CC3M.' },
      { id: 'yolo-world-19', kind: 'concepto', q: '¿Qué es prompt-then-detect?', a: 'Codificar el vocabulario una vez (offline) y re-parametrizarlo como pesos del modelo; la inferencia no corre el text encoder.' },
      { id: 'yolo-world-20', kind: 'concepto', q: '¿Qué hace la max-sigmoid attention y por qué max y sigmoide?', a: 'Re-pondera los canales de cada posición con σ(similitud máxima al vocabulario). Max: invariante al número y orden de las palabras. Sigmoide: cada posición se pondera sola, sin competir. Lineal en posiciones × V y re-parametrizable.' },
      { id: 'yolo-world-21', kind: 'concepto', q: '¿Qué quitó y qué cambió YOLO-World v2?', a: 'Quitó la image-pooling attention (vocabulario dependiente de la imagen, peor tras exportar) y cambió la L2-norm de la cabeza por BatchNorm (se pliega en la conv).' },
      { id: 'yolo-world-22', kind: 'concepto', q: '¿Cómo se pseudo-etiqueta CC3M?', a: 'Frases nominales (n-gramas) → cajas de GLIP-L → CLIP re-puntúa (√(c·s_r)) y opcionalmente re-etiqueta → NMS por frase 0.5 y umbral 0.3 → filtro por imagen > 0.3.' },
      { id: 'yolo-world-23', kind: 'concepto', q: '¿Por qué α y β en la cabeza contrastiva?', a: 'Los cosenos están en [−1, 1]: α estira el rango (como el logit_scale de CLIP) y β pone el logit por defecto muy negativo, necesario con sigmoide por clase y casi todo fondo.' },
      { id: 'yolo-world-24', kind: 'concepto', q: '¿Cómo se arma el vocabulario de entrenamiento?', a: 'Por mosaico de 4 imágenes: todas las palabras positivas + negativas al azar del dataset, hasta 80 (§3.2).' },
      { id: 'yolo-world-25', kind: 'concepto', q: '¿Por qué CLIP y no BERT, y por qué congelado?', a: 'Tabla 5: CLIP congelado 22.4 AP vs BERT congelado 14.6. Fine-tunear CLIP en O365 baja a 19.3: pierde generalidad.' },
      { id: 'yolo-world-26', kind: 'tradeoff', q: 'YOLO-World vs Grounding DINO.', a: 'YOLO-World: denso, fusión liviana, texto offline, tiempo real; en LVIS zero-shot incluso supera a Grounding DINO-T y -L (35.4 vs 27.4 y 33.9). Grounding DINO: DETR con fusión profunda y BERT por imagen; mejor en COCO y con frases referenciales.' },
      { id: 'yolo-world-27', kind: 'tradeoff', q: 'Fine-tunear todo vs prompt tuning.', a: 'Todo: más mAP en tus clases, pierde zero-shot (Tabla 8: −0.6 AP_r de caja). Prompt tuning: solo los embeddings de tus clases, el resto intacto.' },
      { id: 'yolo-world-28', kind: 'tradeoff', q: 'YOLO-World vs YOLOE.', a: 'YOLOE: mismo nicho de tiempo real, sin fusión en el neck (RepRTA re-parametrizable), con prompts visuales y sin prompt, y segmenta; su paper reporta +3.5 AP en LVIS sobre YOLO-Worldv2-S.' },
      { id: 'yolo-world-29', kind: 'tradeoff', q: 'v1 vs v2 en deploy.', a: 'v1: mejor zero-shot por la image-pooling attention, pero el vocabulario depende de la imagen y la cabeza tiene L2: exporta peor (Ultralytics no exporta v1). v2: todo se pliega en convs.' },
      { id: 'yolo-world-30', kind: 'trampa', q: '"Con prompt-then-detect YOLO-World ya no necesita NMS."', a: 'No: quita el text encoder del camino online, no la NMS. Sigue siendo denso con asignación uno a muchos (TAL).' },
      { id: 'yolo-world-31', kind: 'trampa', q: '"La pérdida de clase de YOLO-World es la InfoNCE de CLIP."', a: 'No: TAL asigna positivos y, en el código, es la BCE con sigmoide por clase de YOLOv8 sobre los logits región-texto; los negativos son las otras palabras del vocabulario del mosaico.' },
      { id: 'yolo-world-32', kind: 'trampa', q: '"YOLO-World corre CLIP sobre cada imagen."', a: 'No: solo usa la torre de texto de CLIP, una vez por vocabulario. La imagen la procesa el backbone de YOLOv8.' },
      { id: 'yolo-world-33', kind: 'trampa', q: '"Agregar una clase no cambia las detecciones de las demás."', a: 'En la cabeza, no (cada logit es independiente); en el neck, sí puede: la max-sigmoid toma el máximo sobre todo el vocabulario.' },
      { id: 'yolo-world-34', kind: 'trampa', q: '"Con 1203 clases el modelo es 15× más caro que con 80."', a: 'No: solo la conv 1×1 de la cabeza y las similitudes del neck son lineales en V; lo que crece de verdad es el post-proceso.' },
      { id: 'yolo-world-35', kind: 'trampa', q: '"La re-parametrización es una aproximación que pierde precisión."', a: 'No: es la misma función (lo verificamos: diferencia ≈ 10⁻¹³ en float64). Fija el vocabulario en el artefacto exportado.' },
      { id: 'yolo-world-36', kind: 'trampa', q: '"35.4 AP de YOLO-World-L es su AP en LVIS."', a: 'Es Fixed AP zero-shot en LVIS minival (Tabla 2): sin tope por imagen, hasta 10,000 detecciones por clase en el dataset. Cita partición, protocolo y versión.' },
      { id: 'yolo-world-37', kind: 'conteo', q: 'FPS de YOLO-World-L en la Tabla 2, con y sin text encoder.', a: '52.0 re-parametrizado y 17.6 con el text encoder en el forward, en una V100 sin TensorRT (Grounding DINO-T: 1.5 en la misma tabla).' },
      { id: 'yolo-world-38', kind: 'trampa', q: '"Un umbral de 0.25 sirve para todas las clases de YOLO-World."', a: 'No: las puntuaciones dependen de la palabra, la redacción y el resto del vocabulario. Umbral por clase en validación, y recalibrar al cambiar el vocabulario.' },
      { id: 'yolo-world-39', kind: 'concepto', q: '¿Qué parte de la max-sigmoid se vuelve pesos al re-parametrizar?', a: 'El texto proyectado: una conv 1×1 agrupada (nh grupos, V salidas cada uno) seguida de un máximo sobre V por grupo. La conv 3×3 del project_conv no cambia.' },
      { id: 'yolo-world-40', kind: 'trampa', q: '"Para que no detecte cascos escribo \'not a helmet\'."', a: 'No hay negación, solo similitud: agrega clases distractoras que absorban los falsos positivos y descártalas en el post-proceso.' },
      { id: 'yolo-world-41', kind: 'trampa', q: R`"Grounding DINO-T a 896×1344 cuesta ${qn('metrics.gdinoToYoloWorldMacs')} veces los MACs de YOLO-World-L, y por eso es unas 35 veces más lento (52.0 vs 1.5 FPS)."`, a: R`Esa cifra es sobre todo resolución: a 672×672 cuesta ${qn('metrics.gdino672ToYoloWorldMacs')} veces. La brecha de FPS viene de la atención deformable limitada por memoria, BERT por imagen, el decoder secuencial y el runtime.` },
      { id: 'yolo-world-42', kind: 'trampa', q: '"YOLO-World es de vocabulario abierto: mi robot frenará ante cualquier obstáculo."', a: 'No: solo detecta lo que nombras. Para lo desconocido, objectness class-agnostic u open-world, y una capa geométrica (profundidad, ocupación) para la seguridad.' },
    ],

    // ---------------------------------------------------------- glosario
    glossary: [
      { en: 'open-vocabulary detection', es: 'detección de vocabulario abierto', def: 'Detectar clases definidas por texto (o por ejemplos) en inferencia, incluidas clases que no tenían cajas en el entrenamiento.', say: 'Open-vocabulary detection lets you specify the classes as text at inference time.' },
      { en: 'prompt-then-detect', es: 'primero el prompt, después detectar', def: 'Codificar el vocabulario una vez, offline, y re-parametrizarlo como pesos; la inferencia por imagen no corre el text encoder.', say: 'With prompt-then-detect the vocabulary is encoded once and folded into the weights.' },
      { en: 're-parameterization', es: 're-parametrización', def: 'Reescribir una parte del modelo con otros pesos que calculan la misma función (p. ej. embeddings de texto como pesos de una conv 1×1, o BN plegada en la conv).', say: 'Re-parameterization turns the text embeddings into fixed 1×1 conv weights.' },
      { en: 'RepVL-PAN', es: 'PAN visión-lenguaje re-parametrizable', def: 'El neck de YOLO-World: el PAN de YOLOv8 con T-CSPLayers (texto → imagen) y, en la v1, image-pooling attention (imagen → texto).', say: 'RepVL-PAN injects the vocabulary into the multi-scale features.' },
      { en: 'T-CSPLayer', es: 'capa CSP guiada por texto', def: 'Un C2f con una max-sigmoid attention al final que re-pondera las features por su similitud máxima con el vocabulario.', say: 'Each C2f in the neck becomes a text-guided CSP layer.' },
      { en: 'max-sigmoid attention', es: 'atención max-sigmoide', def: 'Gate por posición: sigmoide de la similitud máxima entre la feature y los embeddings del vocabulario; no mezcla contenido del texto.', say: 'Max-sigmoid attention gates each position by its best-matching vocabulary entry.' },
      { en: 'image-pooling attention', es: 'atención con pooling de imagen', def: 'Actualiza los embeddings de texto con multi-head attention sobre 27 tokens de imagen (max pooling 3×3 de tres niveles); la v2 la quitó.', say: 'Image-pooling attention makes the text embeddings image-aware.' },
      { en: 'region-text contrastive head', es: 'cabeza contrastiva región-texto', def: 'Rama de clase que da un embedding por punto y puntúa cada clase como coseno escalado (α) y desplazado (β) con su embedding de texto.', say: 'Class scores are scaled cosine similarities between region and text embeddings.' },
      { en: 'object embedding', es: 'embedding de objeto', def: 'Vector que la rama de clase produce en cada punto de anclaje, en el mismo espacio que los embeddings de texto.', say: 'The head outputs an object embedding at every anchor point.' },
      { en: 'pseudo-labeling', es: 'pseudo-etiquetado', def: 'Generar cajas automáticamente con un modelo existente (GLIP, filtrado con CLIP) para convertir pares imagen-texto en datos de detección.', say: 'Caption data was pseudo-labeled with GLIP and filtered with CLIP.' },
      { en: 'task-aligned assignment (TAL)', es: 'asignación alineada a la tarea', def: 'Asignación de YOLOv8 (de TOOD): cada GT toma los top-k puntos según una métrica que combina puntuación de clase e IoU; uno a muchos.', say: 'YOLO-World keeps YOLOv8\'s task-aligned assignment, so it still needs NMS.' },
      { en: 'Fixed AP', es: 'AP fijo', def: 'Protocolo de LVIS (Dave et al., 2021) que quita el tope habitual de 300 detecciones por imagen y, en su lugar, limita cada clase a 10,000 detecciones en todo el dataset, para que el AP no dependa de cuántas clases compiten en cada imagen y las raras no queden fuera. YOLO-World además deja hasta 1000 predicciones por imagen (§4.2).', say: 'Zero-shot LVIS results are reported as Fixed AP on minival.' },
    ],
  });
})(typeof window !== 'undefined' ? window : globalThis);
